import{u as c,v as o$,w as p,x as Y,y as C,z as B,A as l$}from"./geo-CGP7liaS.js";import{r as d$,p as h$,f as b$,k as x$,b as y$}from"./geoBC-CRi1g-Mw.js";import{gp as o,gr as f}from"./index-DfOdMJ0P.js";import{I as u$,T as l}from"./util-D-OHAPAJ.js";const M=u$,i=($,e)=>({kind:"squares",start:{a:$,b:e},max:12}),O=$=>Math.round($*10)/10,x="אם יוצא מספר לא שלם, עגלו לעשירית.",v=$=>Number.isInteger(Math.sqrt($)),g=$=>v($)?`= ${Math.sqrt($)}`:`\\approx ${O(Math.sqrt($))}`,A=$=>Math.abs($-Math.round($))<1e-9?Math.round($):O($),W=($,e)=>{const t=[...e];for(let s=t.length-1;s>0;s-=1){const a=Math.floor($()*(s+1));[t[s],t[a]]=[t[a],t[s]]}return t},F=($,e=M)=>{const[t,s,a]=f($,e);return $()<.5?{a:t,b:s,c:a}:{a:s,b:t,c:a}},k$=$=>{for(;;){const e=o($,2,12),t=o($,2,12);if(!v(e*e+t*t))return{a:e,b:t,c:Math.sqrt(e*e+t*t)}}},w$=$=>{for(;;){const e=o($,5,20),t=o($,Math.ceil(e/3),e-1);if(!v(e*e-t*t))return{a:t,b:Math.sqrt(e*e-t*t),c:e}}},G=$=>$()<.5?F($):k$($),K=$=>$()<.5?F($):w$($),b=$=>$.a*$.a+$.b*$.b,f$={params:G,text:$=>`במשולש ישר־זווית הניצבים $${$.a}$ ס״מ ו־$${$.b}$ ס״מ. מה אורך היתר? ${x}`,display:$=>`a = ${$.a},\\ b = ${$.b},\\ c = ?`,answer:$=>A($.c),exact:$=>$.c,bugs:{"add-legs":$=>$.a+$.b,"no-root":b},solution:$=>[`מרבעים כל ניצב: $${$.a}^2 = ${$.a*$.a}$, $${$.b}^2 = ${$.b*$.b}$.`,`מחברים את השטחים: $c^2 = ${$.a*$.a} + ${$.b*$.b} = ${b($)}$.`,`זה שטח הריבוע על היתר. האורך הוא השורש: $c = \\sqrt{${b($)}} ${g(b($))}$ ס״מ.`],hint:$=>`מחברים את שטחי הריבועים על הניצבים, $${$.a}^2 + ${$.b}^2$, ובסוף מוציאים שורש.`,unit:"ס״מ"},g$={params:$=>({k:$()<.5?0:1,...G($)}),text:$=>$.k===0?`יואב הלך $${$.a}$ מטר מזרחה, ואז $${$.b}$ מטר צפונה. כמה מטרים הוא רחוק עכשיו מנקודת ההתחלה, בקו ישר? ${x}`:`על הניצבים של משולש ישר־זווית בנו ריבועים. לאחד שטח $${$.a*$.a}$ סמ״ר ולשני $${$.b*$.b}$ סמ״ר. מה אורך היתר, בס״מ? ${x}`,answer:$=>A($.c),exact:$=>$.c,bugs:{"add-legs":$=>$.a+$.b,"no-root":b},solution:$=>$.k===0?["מזרחה וצפונה נפגשים בזווית ישרה. הדרך בקו ישר היא היתר.",`$d^2 = ${$.a}^2 + ${$.b}^2 = ${$.a*$.a} + ${$.b*$.b} = ${b($)}$`,`$d = \\sqrt{${b($)}} ${g(b($))}$ מטר.`]:[`השטחים כבר נתונים. הריבוע על היתר הוא הסכום שלהם: $${$.a*$.a} + ${$.b*$.b} = ${b($)}$.`,`אורך היתר הוא הצלע של הריבוע הזה: $\\sqrt{${b($)}} ${g(b($))}$ ס״מ.`],hint:$=>$.k===0?"מזרחה וצפונה נפגשים בזווית ישרה, והדרך בקו ישר היא היתר.":"הריבוע על היתר שווה לשני הריבועים יחד. אורך הצלע של ריבוע הוא השורש של השטח שלו."},p$={skill:"pyth:1",topic:"pyth",level:1,title:"מציאת היתר",objectives:["לזהות במשולש ישר־זווית את הניצבים ואת היתר.","להבין למה הריבוע על היתר שווה לשני הריבועים על הניצבים יחד, ורק במשולש ישר־זווית.","לחשב יתר: לרבע כל ניצב, לחבר ולהוציא שורש."],idea:"במשולש ישר־זווית, הריבוע שבנוי על היתר שווה בשטחו לשני הריבועים שבנויים על הניצבים יחד. מחברים את השטחים, והיתר הוא השורש של הסכום.",why:["קחו ארבעה עותקים של המשולש וסדרו אותם בתוך ריבוע גדול שצלעו $a + b$, כך שבאמצע נשאר חור אחד. בגלל הזווית הישרה החור הוא ריבוע שצלעו היתר, בשטח $c^2$.","אפשר לסדר את אותם ארבעה משולשים אחרת באותו ריבוע גדול, כך שנשארים שני חורים: ריבוע בשטח $a^2$ וריבוע בשטח $b^2$.","בשני הסידורים זה אותו ריבוע גדול פחות אותם ארבעה משולשים. לכן החורים שווים בשטחם: $c^2 = a^2 + b^2$.","החשבון נותן שטח. אורך הצלע של ריבוע הוא המספר שכפול עצמו נותן את השטח, כלומר השורש."],alt:["חשבו על אריחים. על ניצב $3$ עומד ריבוע של $9$ אריחים, ועל ניצב $4$ ריבוע של $16$. אם מפרקים את שניהם, $25$ האריחים בונים בדיוק את הריבוע על היתר: $5 \\cdot 5$.","בדיקת שכל: היתר ארוך מכל ניצב, אבל קצר מסכום שני הניצבים, כי קו ישר הוא הדרך הקצרה. לניצבים $6$ ו־$8$ היתר בין $8$ ל־$14$, והוא $10$.","לא תמיד יוצא מספר שלם. לניצבים $1$ ו־$2$: $c^2 = 1 + 4 = 5$, והיתר הוא $\\sqrt{5}$, קצת יותר מ־$2.2$."],discover:[{kind:"say",fig:c(3,4,{labels:{a:"ניצב",b:"ניצב",c:"יתר"},hiHyp:!0}),mood:"happy",text:"במשולש ישר־זווית יש זווית של $90^\\circ$. שתי הצלעות שיוצרות אותה נקראות ניצבים. הצלע שמולה נקראת יתר."},{kind:"predict",fig:c(3,4,{labels:{a:"3",b:"4",c:"?"}}),text:"למשולש ישר־זווית יש ניצבים $3$ ו־$4$. מה לדעתכם אורך היתר?",choices:["$7$","$5$","$4$"],answer:1,why:"היתר ארוך מכל ניצב, אז יותר מ־$4$. אבל הוא הדרך הישרה בין קצות הניצבים, ולכן קצר מ־$3 + 4 = 7$. עוד מעט נראה למה הוא בדיוק $5$.",wrongWhy:{0:"$7$ הוא הדרך לאורך שני הניצבים. היתר הוא קיצור דרך, ולכן קצר יותר.",2:"היתר הוא הצלע הארוכה ביותר במשולש ישר־זווית, ולכן הוא ארוך מ־$4$."}},{kind:"say",fig:c(3,4,{squares:{a:"9",b:"16",c:"?"}}),text:"הסוד הוא לא באורכים אלא בשטחים. נבנה ריבוע על כל צלע. על ניצב $3$ עומד ריבוע בשטח $3^2 = 9$, ועל ניצב $4$ ריבוע בשטח $4^2 = 16$."},{kind:"explore",text:"שנו את הניצבים ועקבו אחרי שלושת השטחים. בנו משולש שהריבוע על היתר שלו בשטח $25$.",manip:i(2,2),answer:{c:5,a:3,b:4},hint:"נסו ניצבים $3$ ו־$4$. כמה זה $9 + 16$?",success:"ניצבים $3$ ו־$4$: השטחים $9$ ו־$16$, ועל היתר בדיוק $25$. שני הריבועים הקטנים יחד שווים לגדול."},{kind:"predict",fig:c(6,8,{squares:{a:"36",b:"64",c:"?"}}),text:"ניצבים $6$ ו־$8$. מה יהיה השטח של הריבוע על היתר?",choices:["$14$","$100$","$48$"],answer:1,why:"מרבעים כל ניצב: $6^2 + 8^2 = 36 + 64 = 100$. מחברים שטחים, לא אורכים.",wrongWhy:{0:"$14$ הוא $6 + 8$, סכום האורכים. השטחים הם $36$ ו־$64$.",2:"$48$ הוא $6 \\cdot 8$. כל ריבוע עומד על צלע אחת: $6 \\cdot 6$ ו־$8 \\cdot 8$."}},{kind:"explore",text:"בדקו בבנייה: מצאו ניצבים שנותנים על היתר ריבוע בשטח $100$.",manip:i(2,2),answer:{c:10,a:6,b:8},hint:"קבעו ניצב אחד $6$. כמה חסר מ־$36$ עד $100$, ואיזה ניצב נותן ריבוע כזה?",success:"$36 + 64 = 100$. מצאנו את השטח של הריבוע על היתר. אבל כמה ארוך היתר עצמו?"},{kind:"predict",fig:c(6,8,{labels:{a:"6",b:"8",c:"?"},squares:{c:"100"}}),text:"הריבוע על היתר בשטח $100$. מה אורך היתר?",choices:["$100$","$10$","$50$"],answer:1,why:"אורך הצלע של ריבוע הוא המספר שכפול עצמו נותן את השטח: $10 \\cdot 10 = 100$. זה השורש: $\\sqrt{100} = 10$.",wrongWhy:{0:"$100$ הוא השטח של הריבוע. יתר באורך $100$ היה ארוך הרבה יותר מסכום הניצבים, $6 + 8 = 14$, וזה לא ייתכן.",2:"חצי מהשטח הוא לא הצלע. מחפשים מספר שכפול עצמו נותן $100$."}},{kind:"predict",fig:o$(),text:"האם זה עובד בכל משולש? משולש עם צלעות $3$ ו־$4$, והזווית ביניהן קהה, גדולה מ־$90^\\circ$. הצלע השלישית:",choices:["שווה ל־$5$","ארוכה מ־$5$","קצרה מ־$5$"],answer:1,why:"כשפותחים את הזווית מעבר ל־$90^\\circ$, הקצוות מתרחקים והצלע השלישית ארוכה מ־$5$. הריבוע עליה גדול מ־$25$. לכן השוויון נכון רק כשהזווית ישרה בדיוק.",wrongWhy:{0:"$5$ רק כשהזווית ישרה בדיוק. פתחנו אותה יותר, והקצוות התרחקו.",2:"צלע קצרה יוצאת כשסוגרים את הזווית. כאן פותחים אותה, והקצוות מתרחקים."}},{kind:"rule",fig:c(3,4,{labels:{a:"a",b:"b",c:"c"}}),text:"משפט פיתגורס: במשולש ישר־זווית, ריבוע היתר שווה לסכום ריבועי הניצבים. לכן היתר הוא השורש של הסכום.",display:"a^2 + b^2 = c^2 \\quad\\Rightarrow\\quad c = \\sqrt{a^2 + b^2}",why:"ארבעה עותקים של המשולש ממלאים ריבוע שצלעו $a + b$ בשני סידורים. באחד נשאר חור $c^2$, ובשני נשארים $a^2$ ו־$b^2$. אותו ריבוע פחות אותם משולשים, ולכן $c^2 = a^2 + b^2$. את האורך מקבלים מהשטח בשורש."},{kind:"explore",text:"נסו לבד: בנו משולש שהיתר שלו $13$.",manip:i(2,2),answer:{c:13,a:5,b:12},hint:"הריבוע על היתר צריך להיות $13^2 = 169$. נסו ניצב $5$: כמה חסר מ־$25$ עד $169$?",success:"$25 + 144 = 169 = 13^2$. ניצבים $5$ ו־$12$ נותנים יתר $13$."}],examples:[{problem:"במשולש ישר־זווית הניצבים $9$ ס״מ ו־$12$ ס״מ. מה אורך היתר?",display:"a = 9,\\ b = 12,\\ c = ?",answer:15,check:"sqrt(9^2 + 12^2)",fig:c(9,12,{labels:{a:"9",b:"12",c:"?"}}),steps:[{action:"מרבעים כל ניצב.",why:"על כל ניצב עומד ריבוע, וזה השטח שלו.",result:"9^2 = 81,\\quad 12^2 = 144",calc:{expr:"9^2",value:81}},{action:"מחברים את השטחים.",why:"שני הריבועים על הניצבים יחד שווים לריבוע על היתר.",result:"c^2 = 81 + 144 = 225",calc:{expr:"81 + 144",value:225}},{action:"מוציאים שורש.",why:"$225$ הוא שטח הריבוע על היתר. האורך הוא המספר שכפול עצמו נותן $225$.",result:"c = \\sqrt{225} = 15",value:"sqrt(225)"},{action:"בודקים בשכל.",why:"היתר ארוך מהניצב הארוך, $12$, וקצר מסכום הניצבים, $9 + 12 = 21$.",result:"12 < 15 < 21",calc:{expr:"9 + 12",value:21}}]},{problem:"גינה מלבנית באורך $12$ מטר וברוחב $5$ מטר. נועה חוצה אותה באלכסון, מפינה לפינה. כמה מטרים היא הולכת?",answer:13,check:"sqrt(12^2 + 5^2)",fig:d$(12,5,{w:"12",h:"5",d:"?"},"גינה מלבנית והאלכסון שחוצה אותה"),steps:[{action:"מוצאים משולש ישר־זווית: שתי צלעות של המלבן והאלכסון.",why:"בפינה של מלבן יש זווית ישרה. האלכסון מולה, ולכן הוא היתר.",result:"a = 12,\\ b = 5,\\ c = ?"},{action:"מרבעים ומחברים.",why:"מחפשים את היתר, ולכן מחברים את הריבועים על הניצבים.",result:"c^2 = 12^2 + 5^2 = 144 + 25 = 169",calc:{expr:"12^2 + 5^2",value:169}},{action:"מוציאים שורש.",why:"$169$ הוא שטח. האורך הוא $13$, כי $13 \\cdot 13 = 169$.",result:"c = \\sqrt{169} = 13",value:"sqrt(169)"},{action:"מפרשים.",why:"מסביב לגינה הולכים $12 + 5 = 17$ מטר. באלכסון חוסכים $4$ מטר.",result:"17 - 13 = 4",calc:{expr:"12 + 5 - 13",value:4}}]}],together:[{problem:"נמצא יחד את היתר.",display:"a = 8,\\ b = 15,\\ c = ?",fig:c(8,15,{labels:{a:"8",b:"15",c:"?"}}),steps:[{prompt:"מה עושים קודם?",choices:[{text:"מרבעים כל ניצב: $64$ ו־$225$",ok:!0,feedback:"נכון: אלה השטחים של הריבועים על הניצבים."},{text:"מחברים את הניצבים: $8 + 15 = 23$",ok:!1,misc:"add-legs",feedback:"מחברים שטחים של ריבועים, לא אורכים. $23$ הוא הדרך לאורך שני הניצבים, והיתר קצר ממנה."},{text:"מחסרים: $15 - 8 = 7$",ok:!1,feedback:"היתר הוא הצלע הארוכה ביותר, ולכן הוא ארוך מ־$15$. חיסור נותן משהו קצר מדי."}],hints:["על כל ניצב עומד ריבוע. מה השטח שלו?","השטח של הריבוע על ניצב $8$ הוא $8^2 = 64$, ועל ניצב $15$ הוא $15^2 = 225$."],done:"$8^2 = 64$, $15^2 = 225$"},{prompt:"ומה עכשיו?",choices:[{text:"מחברים: $c^2 = 64 + 225 = 289$",ok:!0,feedback:"נכון: שני הריבועים על הניצבים יחד הם הריבוע על היתר."},{text:"מחסרים: $225 - 64 = 161$",ok:!1,feedback:"מחסרים כשמחפשים ניצב. כאן מחפשים את היתר, והריבוע עליו הוא שני הקטנים יחד."},{text:"כופלים: $64 \\cdot 225$",ok:!1,feedback:"הריבוע על היתר שווה לסכום של שני הריבועים, לא למכפלה שלהם."}],hints:["איך הריבוע על היתר קשור לשני הריבועים על הניצבים?","שני הריבועים הקטנים יחד שווים לגדול: $64 + 225$."],done:"$c^2 = 289$"},{prompt:"קיבלנו $c^2 = 289$. מה המספר הזה?",choices:[{text:"השטח של הריבוע על היתר. האורך הוא השורש שלו.",ok:!0,feedback:"בדיוק. נשאר להוציא שורש."},{text:"האורך של היתר",ok:!1,misc:"no-root",feedback:"$289$ הוא שטח. יתר באורך $289$ היה ארוך הרבה יותר מסכום הניצבים, $8 + 15 = 23$, וזה לא ייתכן."}],hints:["$c^2$ הוא $c$ כפול $c$. מה זה אומר על ריבוע שצלעו $c$?","$c^2$ הוא השטח של הריבוע על היתר. האורך הוא המספר שכפול עצמו נותן $289$."],done:"מוציאים שורש: $c = \\sqrt{289}$"}],final:{prompt:"מה אורך היתר?",answer:17,check:"sqrt(8^2 + 15^2)",hints:["איזה מספר כפול עצמו נותן $289$? נסו מספרים בין $15$ ל־$20$.","$17 \\cdot 17 = 289$."]}},{problem:"דני פתר: ניצבים $20$ ו־$21$, ולכן היתר $20 + 21 = 41$. נבדוק אותו.",display:"a = 20,\\ b = 21,\\ c = ?",fig:c(20,21,{labels:{a:"20",b:"21",c:"?"}}),steps:[{prompt:"מה הבעיה בפתרון של דני?",choices:[{text:"הוא חיבר אורכים במקום שטחים של ריבועים",ok:!0,feedback:"נכון. $41$ הוא הדרך לאורך שני הניצבים, והיתר קצר ממנה."},{text:"הוא שכח להוציא שורש",ok:!1,feedback:"דני לא ריבע בכלל, ולכן אין ממה להוציא שורש. החיבור עצמו שגוי."},{text:"אין בעיה, הפתרון נכון",ok:!1,misc:"add-legs",feedback:"בדקו בשכל: היתר צריך להיות קצר מסכום הניצבים, ו־$41$ שווה לו בדיוק."}],hints:["מה מחברים במשפט פיתגורס: את האורכים או את הריבועים?","מחברים את הריבועים: $20^2 + 21^2$, ולא $20 + 21$."],done:"$c^2 = 20^2 + 21^2 = 400 + 441 = 841$"}],final:{prompt:"מה אורך היתר באמת?",answer:29,check:"sqrt(20^2 + 21^2)",hints:["$c^2 = 841$. איזה מספר כפול עצמו נותן $841$? הוא קצת קטן מ־$30$.","$29 \\cdot 29 = 841$."]}}],diag:f$,transfer:g$,misconceptions:[{id:"add-legs",title:"חיברו את אורכי הניצבים, במקום את השטחים של הריבועים",cause:"המשפט מחבר שטחים של ריבועים, לא אורכים. $a + b$ הוא הדרך לאורך שני הניצבים, והיתר הוא קיצור הדרך.",explain:["נראה שחיברתם את האורכים עצמם. אבל המשפט מדבר על הריבועים שעומדים על הצלעות.","ניצבים $3$ ו־$4$: $3 + 4 = 7$, אבל היתר הוא $5$. קו ישר תמיד קצר מהדרך לאורך שני הניצבים.","מחברים שטחים: $9 + 16 = 25$, ורק אז מוציאים שורש: $\\sqrt{25} = 5$."],remedy:[{kind:"explore",text:"קבעו ניצבים $6$ ו־$8$ והסתכלו על השטח שיוצא על היתר.",manip:i(2,2),answer:{c:10,a:6,b:8},hint:"הניצבים צריכים להיות $6$ ו־$8$.",success:"על היתר $36 + 64 = 100$, ולכן היתר $10$, ולא $6 + 8 = 14$."},{kind:"predict",text:"ניצבים $5$ ו־$12$. מה אורך היתר?",choices:["$17$","$13$"],answer:1,why:"$17$ הוא הדרך לאורך שני הניצבים. מחברים שטחים: $25 + 144 = 169$, והיתר $\\sqrt{169} = 13$."}]},{id:"no-root",title:"עצרו ב־$c^2$ ושכחו להוציא שורש",cause:"הסכום $a^2 + b^2$ הוא השטח של הריבוע על היתר, לא האורך של היתר.",explain:["החישוב היה נכון כמעט עד הסוף. אבל $a^2 + b^2$ הוא שטח, והשאלה הייתה על אורך.","אורך הצלע של ריבוע ששטחו $25$ הוא $5$, כי $5 \\cdot 5 = 25$. לכן בסוף מוציאים שורש.","בדיקת שכל: לניצבים $3$ ו־$4$ יתר של $25$ ארוך הרבה יותר מסכום הניצבים, וזה לא ייתכן."],remedy:[{kind:"predict",text:"ריבוע ששטחו $49$. מה אורך הצלע שלו?",choices:["$49$","$7$","$24.5$"],answer:1,why:"$7 \\cdot 7 = 49$, ולכן הצלע $7$. אורך מקבלים מהשטח בשורש: $\\sqrt{49} = 7$."},{kind:"explore",text:"בנו משולש שהריבוע על היתר שלו בשטח $169$.",manip:i(2,2),answer:{c:13,a:5,b:12},hint:"נסו ניצב $5$. כמה חסר מ־$25$ עד $169$?",success:"השטח על היתר $169$, אבל היתר עצמו $13$, כי $13 \\cdot 13 = 169$. זה השורש שחסר בסוף."},{kind:"predict",text:"ניצבים $9$ ו־$12$, ויצא $c^2 = 225$. מה אורך היתר?",choices:["$225$","$15$"],answer:1,why:"$225$ הוא השטח. היתר הוא $\\sqrt{225} = 15$, ארוך מ־$12$ וקצר מ־$21$, כמו שצריך."}]}]},U={"add-not-sub":$=>Math.sqrt($.c*$.c+$.a*$.a),"subtract-sides":$=>$.c-$.a,"no-root":$=>$.c*$.c-$.a*$.a},y=$=>$.c*$.c-$.a*$.a,m$={params:K,text:$=>`במשולש ישר־זווית היתר $${$.c}$ ס״מ, וניצב אחד $${$.a}$ ס״מ. מה אורך הניצב השני? ${x}`,display:$=>`c = ${$.c},\\ a = ${$.a},\\ b = ?`,answer:$=>A($.b),exact:$=>$.b,bugs:U,solution:$=>[`היתר ידוע, ולכן הריבוע עליו הוא השלם: $${$.c}^2 = ${$.c*$.c}$.`,`מחסרים את הריבוע על הניצב הידוע: $b^2 = ${$.c*$.c} - ${$.a*$.a} = ${y($)}$.`,`מוציאים שורש: $b = \\sqrt{${y($)}} ${g(y($))}$ ס״מ, קצר מהיתר כמו שצריך.`],hint:$=>`הריבוע על היתר הוא השלם. מחסרים ממנו את הריבוע על הניצב הידוע: $${$.c}^2 - ${$.a}^2$.`,unit:"ס״מ"},q$={params:$=>({k:$()<.5?0:1,...K($)}),text:$=>$.k===0?`האלכסון של מלבן $${$.c}$ ס״מ, ואחת מצלעותיו $${$.a}$ ס״מ. מה אורך הצלע השנייה? ${x}`:`במשולש ישר־זווית, לריבוע שבנוי על היתר שטח $${$.c*$.c}$ סמ״ר, ולריבוע שבנוי על אחד הניצבים שטח $${$.a*$.a}$ סמ״ר. מה אורך הניצב השני, בס״מ? ${x}`,answer:$=>A($.b),exact:$=>$.b,bugs:U,solution:$=>$.k===0?["שתי צלעות של מלבן נפגשות בזווית ישרה, והאלכסון מולה: הוא היתר.",`$b^2 = ${$.c}^2 - ${$.a}^2 = ${$.c*$.c} - ${$.a*$.a} = ${y($)}$`,`$b = \\sqrt{${y($)}} ${g(y($))}$ ס״מ.`]:[`הריבוע על היתר הוא השלם. הריבוע על הניצב החסר הוא מה שנשאר: $${$.c*$.c} - ${$.a*$.a} = ${y($)}$.`,`אורך הניצב הוא הצלע של הריבוע הזה: $\\sqrt{${y($)}} ${g(y($))}$ ס״מ.`],hint:$=>$.k===0?"האלכסון של המלבן הוא היתר. מחפשים צלע, כלומר ניצב: מחסרים ריבועים.":"השטח של הריבוע על היתר הוא השלם, והשטח על הניצב הידוע הוא חלק ממנו. מה נשאר?"},v$={skill:"pyth:2",topic:"pyth",level:2,title:"מציאת ניצב",objectives:["לזהות מתי היתר נתון והחסר הוא ניצב.","למצוא ניצב בחיסור שטחים, $b^2 = c^2 - a^2$, ואז להוציא שורש.","לבדוק שהניצב שיצא קצר מהיתר ומקיים את המשפט."],idea:"כשהיתר ידוע, הריבוע עליו הוא השלם, והריבועים על הניצבים הם החלקים. חלק חסר מוצאים בחיסור: $b^2 = c^2 - a^2$, ואז מוציאים שורש.",why:["משפט פיתגורס אומר ששני הריבועים על הניצבים יחד הם בדיוק הריבוע על היתר. אם אחד מהם ידוע, השני הוא מה שנשאר מהשלם.","זה כמו $9 + ? = 25$: את החסר מוצאים בחיסור, $25 - 9 = 16$.","החיסור נותן את השטח של הריבוע על הניצב החסר. האורך שלו הוא השורש של השטח."],alt:["דמיינו שהריבוע על היתר עשוי אריחים. מעבירים ממנו לריבוע על הניצב הידוע את האריחים שהוא צריך. מה שנשאר בונה בדיוק את הריבוע על הניצב השני.","כתבו את המשפט כמשוואה: $6^2 + b^2 = 10^2$, כלומר $36 + b^2 = 100$. מחסרים $36$ משני האגפים: $b^2 = 64$, ולכן $b = 8$.","בדיקת שכל: ניצב תמיד קצר מהיתר. אם יצא ניצב ארוך מהיתר, כנראה חיברתם במקום לחסר."],discover:[{kind:"say",fig:c(6,8,{labels:{a:"ניצב",b:"?",c:"יתר"},hiHyp:!0}),mood:"happy",text:"עד עכשיו ידענו את שני הניצבים וחיפשנו את היתר. עכשיו הפוך: היתר ידוע, וניצב אחד חסר."},{kind:"predict",fig:c(6,8,{labels:{a:"6",b:"?",c:"10"}}),text:"במשולש ישר־זווית היתר $10$ וניצב אחד $6$. הניצב השני ארוך או קצר מ־$10$?",choices:["ארוך מ־$10$","קצר מ־$10$","אי אפשר לדעת"],answer:1,why:"היתר הוא הצלע הארוכה ביותר במשולש ישר־זווית. כל ניצב קצר ממנו.",wrongWhy:{0:"אז הוא היה הצלע הארוכה. אבל היתר הוא תמיד הארוך ביותר.",2:"אפשר: היתר הוא תמיד הצלע הארוכה ביותר. לכן כל ניצב קצר ממנו."}},{kind:"say",fig:c(6,8,{squares:{a:"36",b:"?",c:"100"}}),text:"נחשוב על השטחים. על היתר עומד ריבוע בשטח $10^2 = 100$, ועל הניצב הידוע ריבוע בשטח $6^2 = 36$. הפעם הריבוע הגדול כבר ידוע: הוא השלם."},{kind:"predict",fig:c(6,8,{squares:{a:"36",b:"?",c:"100"}}),text:"שני הריבועים על הניצבים יחד הם $100$. אחד מהם $36$. מה השטח של השני?",choices:["$136$","$64$","$4$"],answer:1,why:"$36 + ? = 100$, ולכן החסר הוא $100 - 36 = 64$.",wrongWhy:{0:"$136$ גדול מהריבוע על היתר, אבל הוא אמור להיות חלק ממנו. כשמחפשים חלק, מחסרים.",2:"$4$ הוא $10 - 6$, הפרש האורכים. מחסרים שטחים: $100 - 36$."}},{kind:"explore",text:"בדקו בבנייה: השאירו ניצב אחד $6$, ושנו את השני עד שהריבוע על היתר יהיה $100$.",manip:i(6,2),answer:{c:10,a:6,b:8},hint:"כמה חסר ל־$36$ כדי להגיע ל־$100$? איזה ניצב נותן ריבוע כזה?",success:"ניצב $8$: $36 + 64 = 100$. הריבוע החסר היה $64$, והצלע שלו $8$."},{kind:"predict",fig:c(6,8,{labels:{a:"6",b:"?",c:"10"},squares:{b:"64"}}),text:"מצאנו שהריבוע על הניצב החסר הוא $64$. מה אורך הניצב?",choices:["$64$","$8$","$32$"],answer:1,why:"$64$ הוא שטח. אורך הצלע הוא המספר שכפול עצמו נותן $64$: $\\sqrt{64} = 8$.",wrongWhy:{0:"$64$ הוא השטח של הריבוע, לא הצלע. איזה מספר כפול עצמו נותן $64$?",2:"$32$ הוא חצי של $64$. אבל $32 \\cdot 32$ גדול בהרבה מ־$64$."}},{kind:"rule",fig:c(3,4,{labels:{a:"a",b:"b",c:"c"}}),text:"מוצאים ניצב: מריבוע היתר מחסרים את ריבוע הניצב הידוע, ומוציאים שורש.",display:"b^2 = c^2 - a^2 \\quad\\Rightarrow\\quad b = \\sqrt{c^2 - a^2}",why:"המשפט $a^2 + b^2 = c^2$ אומר שהריבוע על היתר הוא השלם. החלק החסר הוא השלם פחות החלק הידוע."},{kind:"predict",fig:c(5,12,{labels:{a:"5",b:"?",c:"13"}}),text:"היתר $13$ וניצב $5$. איזה חישוב נכון?",choices:["$13^2 - 5^2$","$5^2 - 13^2$","$13 - 5$"],answer:0,why:"מהשטח הגדול, של היתר, מחסרים את הקטן: $169 - 25 = 144$, והניצב $\\sqrt{144} = 12$.",wrongWhy:{1:"זה יוצא שלילי, ושטח לא יכול להיות שלילי. מתחילים מהשלם, הריבוע על היתר.",2:"מחסרים שטחים, לא אורכים. $13 - 5 = 8$, אבל $5^2 + 8^2 = 89$, ולא $169$."}},{kind:"explore",text:"נסו לבד: היתר $13$ וניצב אחד $5$. מצאו את הניצב השני.",manip:i(5,3),answer:{c:13,a:5,b:12},hint:"$169 - 25 = 144$. איזה ניצב נותן ריבוע של $144$?",success:"$25 + 144 = 169$: הניצב החסר הוא $12$, קצר מהיתר כמו שצריך."},{kind:"say",fig:c(5,12,{labels:{a:"5",b:"12",c:"13"}}),text:"תמיד אפשר לבדוק בסוף: מחזירים את הניצב למשפט. $5^2 + 12^2 = 169 = 13^2$, ולכן צדקנו."}],examples:[{problem:"במשולש ישר־זווית היתר $25$ ס״מ וניצב אחד $7$ ס״מ. מה אורך הניצב השני?",display:"c = 25,\\ a = 7,\\ b = ?",answer:24,check:"sqrt(25^2 - 7^2)",fig:c(7,24,{labels:{a:"7",b:"?",c:"25"}}),steps:[{action:"מזהים מה ידוע: היתר הוא $25$, ומחפשים ניצב.",why:"כשהיתר ידוע, הריבוע עליו הוא השלם, ולכן נחסר.",result:"b^2 = 25^2 - 7^2"},{action:"מרבעים.",why:"עובדים עם השטחים של הריבועים.",result:"25^2 = 625,\\quad 7^2 = 49",calc:{expr:"25^2",value:625}},{action:"מחסרים מהשלם את החלק הידוע.",why:"שני הריבועים על הניצבים יחד הם $625$, ואחד מהם $49$.",result:"b^2 = 625 - 49 = 576",calc:{expr:"625 - 49",value:576}},{action:"מוציאים שורש.",why:"$576$ הוא השטח של הריבוע על הניצב. האורך הוא המספר שכפול עצמו נותן $576$.",result:"b = \\sqrt{576} = 24",value:"sqrt(576)"},{action:"בודקים.",why:"הניצב קצר מהיתר, והמשפט מתקיים.",result:"7^2 + 24^2 = 49 + 576 = 625 = 25^2",calc:{expr:"7^2 + 24^2",value:625}}]},{problem:"כבל באורך $17$ מטר מחובר לראש של תורן ונעוץ בקרקע $8$ מטר מבסיס התורן. מה גובה התורן?",answer:15,check:"sqrt(17^2 - 8^2)",fig:h$(15,8,{h:"?",d:"8",c:"17"}),steps:[{action:"מוצאים את המשולש: התורן, הקרקע והכבל.",why:"התורן עומד זקוף על הקרקע, וביניהם זווית ישרה. הכבל מולה, ולכן הוא היתר.",result:"c = 17,\\ a = 8,\\ h = ?"},{action:"הגובה הוא ניצב, ולכן מחסרים.",why:"הריבוע על הכבל הוא השלם, והריבוע על המרחק בקרקע הוא חלק ממנו.",result:"h^2 = 17^2 - 8^2 = 289 - 64 = 225",calc:{expr:"17^2 - 8^2",value:225}},{action:"מוציאים שורש.",why:"מהשטח לאורך.",result:"h = \\sqrt{225} = 15",value:"sqrt(225)"},{action:"בודקים שהתשובה הגיונית.",why:"התורן קצר מהכבל, כמו שניצב קצר מהיתר.",result:"8^2 + 15^2 = 64 + 225 = 289 = 17^2",calc:{expr:"8^2 + 15^2",value:289}}]}],together:[{problem:"נמצא יחד את הניצב החסר.",display:"c = 20,\\ a = 12,\\ b = ?",fig:c(12,16,{labels:{a:"12",b:"?",c:"20"}}),steps:[{prompt:"איזה ריבוע הוא השלם?",choices:[{text:"הריבוע על היתר, $20^2 = 400$",ok:!0,feedback:"נכון: הריבוע על היתר שווה לשני הריבועים על הניצבים יחד."},{text:"הריבוע על הניצב, $12^2 = 144$",ok:!1,feedback:"הריבוע על ניצב הוא רק חלק. הגדול, השלם, תמיד עומד על היתר."},{text:"אין שלם, מחברים את שניהם",ok:!1,misc:"add-not-sub",feedback:"מחברים כשמחפשים יתר. כאן היתר ידוע, והריבוע שלו כבר הסכום."}],hints:["על איזו צלע עומד הריבוע הגדול ביותר?","היתר הוא הצלע הארוכה, ולכן $20^2 = 400$ הוא השלם."],done:"$20^2 = 400$ הוא השלם."},{prompt:"איך מוצאים את הריבוע על הניצב החסר?",choices:[{text:"$400 - 144 = 256$",ok:!0,feedback:"נכון: השלם פחות החלק הידוע."},{text:"$400 + 144 = 544$",ok:!1,misc:"add-not-sub",feedback:"אז הריבוע על הניצב היה גדול מהריבוע על היתר, וזה לא ייתכן."},{text:"$20 - 12 = 8$",ok:!1,misc:"subtract-sides",feedback:"מחסרים שטחים, לא אורכים. בדקו: $12^2 + 8^2 = 208$, ולא $400$."}],hints:["השלם הוא $400$, וחלק אחד $144$. איך מוצאים את החלק החסר?","השלם פחות החלק: $400 - 144$."],done:"$b^2 = 256$"}],final:{prompt:"מה אורך הניצב?",answer:16,check:"sqrt(20^2 - 12^2)",hints:["איזה מספר כפול עצמו נותן $256$?","$16 \\cdot 16 = 256$."]}},{problem:"ועוד אחד, עם הפתעה.",display:"c = 26,\\ a = 24,\\ b = ?",fig:c(24,10,{labels:{a:"24",b:"?",c:"26"}}),steps:[{prompt:"מה מחשבים?",choices:[{text:"$26^2 - 24^2$",ok:!0,feedback:"נכון: מהשלם מחסרים את החלק הידוע."},{text:"$24^2 - 26^2$",ok:!1,feedback:"זה יוצא שלילי, ושטח לא יכול להיות שלילי. מתחילים מהריבוע על היתר."},{text:"$26^2 + 24^2$",ok:!1,misc:"add-not-sub",feedback:"מחברים כשמחפשים את היתר. כאן היתר נתון, ומחפשים ניצב."}],hints:["מי היתר כאן, ומה הוא אומר לנו?","היתר $26$, והריבוע עליו הוא השלם: $26^2 - 24^2$."],done:"$b^2 = 676 - 576 = 100$"}],final:{prompt:"מה אורך הניצב החסר?",answer:10,check:"sqrt(26^2 - 24^2)",hints:["$b^2 = 100$. איזה מספר כפול עצמו נותן $100$?","$\\sqrt{100} = 10$. ניצב קצר, כי הניצב השני כמעט באורך היתר."]}}],diag:m$,transfer:q$,misconceptions:[{id:"add-not-sub",title:"חיברו ריבועים כמו במציאת יתר, כשהיתר כבר נתון",cause:"הרגל מהשלב הקודם: מרבעים ומחברים. אבל כשהיתר נתון, הריבוע עליו הוא כבר הסכום, ומה שחסר הוא חלק ממנו.",explain:["נראה שחיברתם את שני הריבועים. כך מוצאים יתר, אבל כאן היתר נתון.","הריבוע על היתר הוא השלם. הריבוע על הניצב החסר הוא מה שנשאר אחרי שמורידים ממנו את הריבוע על הניצב הידוע.","סימן אזהרה: אם הניצב שיצא ארוך מהיתר, משהו התבלבל."],remedy:[{kind:"predict",text:"היתר $10$ וניצב $6$. מי שמחבר מקבל $\\sqrt{100 + 36}$, בערך $11.7$. מה לא מסתדר?",choices:["ניצב לא יכול להיות ארוך מהיתר","הכול בסדר"],answer:0,why:"היתר הוא הצלע הארוכה ביותר. ניצב של $11.7$ ארוך מהיתר $10$, ולכן החיבור שגוי. מחסרים: $100 - 36 = 64$, והניצב $8$."},{kind:"explore",text:"השאירו ניצב אחד $6$, ומצאו ניצב שני שייתן יתר $10$.",manip:i(6,11),answer:{c:10,a:6,b:8},hint:"הריבוע על היתר צריך להיות $100$. כמה ממנו כבר תפוס בריבוע של $36$?",success:"הריבוע הגדול, $100$, הוא השלם. $100 - 36 = 64$, והניצב $8$."}]},{id:"subtract-sides",title:"חיסרו את האורכים בלי לרבע",cause:"נכון שצריך לחסר, אבל משפט פיתגורס מדבר על שטחים של ריבועים, לא על האורכים עצמם.",explain:["הכיוון נכון: מחפשים ניצב, ולכן מחסרים. אבל צריך לחסר את הריבועים.","היתר $13$ וניצב $5$: $13 - 5 = 8$, אבל $5^2 + 8^2 = 89$, ולא $169$. ההפרש בין האורכים לא נותן משולש ישר־זווית."],remedy:[{kind:"predict",text:"היתר $13$ וניצב $5$. האם הניצב השני הוא $13 - 5 = 8$?",choices:["כן","לא"],answer:1,why:"בדקו: $5^2 + 8^2 = 25 + 64 = 89$, ולא $169$. מחסרים ריבועים: $169 - 25 = 144$, והניצב $12$."},{kind:"explore",text:"מתחילים מניצבים $5$ ו־$8$. ראו כמה יוצא על היתר, ותקנו את הניצב השני עד שהיתר יהיה $13$.",manip:i(5,8),answer:{c:13,a:5,b:12},hint:"עם $8$ יוצא רק $89$. כמה חסר עד $169$?",success:"$8$ נתן רק $89$. הניצב הנכון הוא $12$: $25 + 144 = 169$."}]},{id:"no-root",title:"מצאו את $b^2$ ושכחו להוציא שורש",cause:"החיסור נותן את השטח של הריבוע על הניצב, לא את אורך הניצב.",explain:["החיסור היה נכון. אבל $c^2 - a^2$ הוא שטח של ריבוע, והשאלה הייתה על אורך.","בדיקת שכל: ניצב צריך להיות קצר מהיתר. מספר כמו $144$ ליתר של $13$ הוא שטח, לא צלע."],remedy:[{kind:"predict",text:"מצאנו $b^2 = 144$. מה אורך הניצב?",choices:["$144$","$12$","$72$"],answer:1,why:"$12 \\cdot 12 = 144$. השטח הוא $144$, והצלע $\\sqrt{144} = 12$."},{kind:"explore",text:"היתר $15$ וניצב אחד $9$: $225 - 81 = 144$. בנו את המשולש: איזה ניצב נותן ריבוע של $144$?",manip:i(9,3),answer:{c:15,a:9,b:12},hint:"השאירו את הניצב $9$, ושנו את השני עד שהריבוע שלו יהיה $144$.",success:"הניצב $12$, והריבוע עליו $144$. האורך הוא השורש של השטח."}],prereq:"pyth:1"}]},H=$=>[...$].sort((e,t)=>e-t),T=$=>{const[e,t,s]=H($);return e*e+t*t===s*s},A$=$=>$[0]*$[0]+$[1]*$[1]===$[2]*$[2],L=$=>$.sets.filter(T).length,S=["א","ב","ג","ד"];function B$($,e){for(;;){const[t,s,a]=f($,e),r=o($,0,3),n=r===0?[t,s,a+o($,1,2)]:r===1?[t,s,a-1]:r===2?[t+1,s,a]:[t,s+1,a],[d,h,I]=H(n);if(d+h>I&&h<I&&!T(n))return W($,n)}}function X($,e=M){const t=o($,0,4),s=W($,[0,1,2,3]).slice(0,t);return[0,1,2,3].map(a=>s.includes(a)?W($,[...f($,e)]):B$($,e))}const J={"wrong-hyp":$=>$.k===1?null:$.sets.filter(A$).length,"assume-right":()=>4,"add-legs":$=>L($)>=2?0:null},M$=($,e,t)=>{const[s,a,r]=H($);return`${t} ${S[e]}, $${$.join(",\\ ")}$: $${s}^2 + ${a}^2 = ${s*s+a*a}$ ו־$${r}^2 = ${r*r}$. ${T($)?"שווים: ישר־זווית.":"לא שווים."}`},V=($,e="משולש")=>["בכל משולש הזווית הישרה, אם יש, מול הצלע הארוכה. משווים את הריבוע שלה לסכום הריבועים של שתי האחרות.",...$.sets.map((t,s)=>M$(t,s,e)),`ישרי־זווית: $${L($)}$.`],C$={params:$=>({sets:X($)}),text:()=>"כמה מהמשולשים בטבלה ישרי־זווית?",fig:$=>({type:"table",head:["משולש","אורכי הצלעות"],rows:$.sets.map((e,t)=>[S[t],e.join(", ")])}),answer:L,bugs:J,solution:$=>V($),hint:()=>"בודקים כל משולש לבד: מוצאים את הצלע הארוכה, ומשווים את הריבוע שלה לסכום הריבועים של שתי האחרות."},W$=[[3,4,5],[6,8,10],[5,12,13],[9,12,15],[8,15,17]],S$={params:$=>{if($()<.5)return{k:0,sets:X($)};const e=o($,0,4),t=W($,[0,1,2,3]).slice(0,e);return{k:1,sets:[0,1,2,3].map(s=>{const[a,r,n]=f($,W$),d=10*n+(t.includes(s)?0:f($,[-2,-1,1,2]));return[10*Math.max(a,r),10*Math.min(a,r),d]})}},text:$=>$.k===1?"נגר בנה ארבע מסגרות, ומדד בכל אחת את הרוחב, הגובה והאלכסון (בס״מ). בכמה מהמסגרות הפינות ישרות?":"לנועה ארבע ערמות של שלושה מקלות (האורכים בס״מ). מכל ערמה היא מניחה משולש. בכמה מהמשולשים יש זווית ישרה?",fig:$=>$.k===1?{type:"table",head:["מסגרת","רוחב","גובה","אלכסון"],rows:$.sets.map((e,t)=>[S[t],...e])}:{type:"table",head:["ערמה","אורכי המקלות"],rows:$.sets.map((e,t)=>[S[t],e.join(", ")])},answer:L,bugs:J,solution:$=>V($,$.k===1?"מסגרת":"ערמה"),hint:$=>$.k===1?"בפינה ישרה הרוחב, הגובה והאלכסון יוצרים משולש ישר־זווית: בודקים בכל מסגרת אם רוחב² + גובה² = אלכסון².":"הזווית הישרה, אם יש, מול המקל הארוך. בכל ערמה משווים את הריבוע שלו לסכום הריבועים של שני האחרים."},P$={skill:"pyth:3",topic:"pyth",level:3,title:"האם המשולש ישר־זווית?",objectives:["להבין שהשוויון $a^2 + b^2 = c^2$ מתקיים רק כשהזווית מול $c$ ישרה.","לבדוק אם משולש ישר־זווית: להשוות את ריבוע הצלע הארוכה לסכום ריבועי שתי האחרות.","לדעת איפה הזווית הישרה: מול הצלע הארוכה, בלי קשר לסדר שבו כתבו את הצלעות."],idea:"המשפט עובד גם הפוך: אם ריבוע הצלע הארוכה שווה בדיוק לסכום ריבועי שתי האחרות, המשולש ישר־זווית, והזווית הישרה מול הצלע הארוכה. אם לא שווה, אין בו זווית ישרה.",why:["נניח ש־$a^2 + b^2 = c^2$. נבנה משולש ישר־זווית עם הניצבים $a$ ו־$b$. לפי משפט פיתגורס היתר שלו הוא $\\sqrt{a^2 + b^2} = c$.","למשולש שבנינו יש אותן שלוש צלעות כמו למשולש שלנו. משולשים עם אותן שלוש צלעות חופפים, ולכן גם במשולש שלנו הזווית מול $c$ ישרה.","ואם לא שווה? חשבו על שתי צלעות שמחוברות בציר. כשהזווית ביניהן חדה, הצלע השלישית קצרה מיתר. כשהיא קהה, ארוכה ממנו. רק בזווית ישרה בדיוק $c^2 = a^2 + b^2$."],alt:["בנאים ונגרים בודקים כך פינות: מסמנים $3$ מטר על קיר אחד ו־$4$ מטר על השני. אם המרחק בין הסימנים בדיוק $5$ מטר, הפינה ישרה.","חשבו על מאזניים: בצד אחד $c^2$, ובצד השני $a^2 + b^2$. מאוזן: הזווית מול $c$ ישרה. $c^2$ כבד יותר: הזווית קהה. קל יותר: חדה."],discover:[{kind:"say",fig:p(10,6,8,{labels:!1}),mood:"happy",text:"עד עכשיו ידענו שהמשולש ישר־זווית. עכשיו השאלה הפוכה: נתונות שלוש צלעות. איך יודעים אם יש במשולש זווית ישרה, בלי לראות אותו?"},{kind:"predict",fig:Y(60),text:"שני מקלות, $6$ ו־$8$, מחוברים בציר. כשהזווית ביניהם ישרה, המרחק בין הקצוות הוא $10$. סוגרים קצת את הציר, לזווית חדה. המרחק בין הקצוות:",choices:["גדל, יותר מ־$10$","קטן, פחות מ־$10$","נשאר $10$"],answer:1,why:"כשסוגרים את הציר, הקצוות מתקרבים. בזווית חדה הצלע השלישית קצרה מ־$10$, והריבוע שלה קטן מ־$100$.",wrongWhy:{0:"כשסוגרים ציר, הקצוות מתקרבים זה לזה. לכן המרחק קטן.",2:"$10$ רק כשהזווית ישרה בדיוק. סגרנו אותה, והקצוות התקרבו."}},{kind:"predict",fig:Y(120),text:"ועכשיו פותחים את הציר מעבר ל־$90^\\circ$, לזווית קהה. הצלע השלישית:",choices:["ארוכה מ־$10$","קצרה מ־$10$"],answer:0,why:"הקצוות מתרחקים, והצלע השלישית ארוכה מ־$10$. רק כשהזווית ישרה בדיוק היא $10$, ורק אז $6^2 + 8^2 = 10^2$.",wrongWhy:{1:"צלע קצרה יוצאת כשסוגרים. כאן פותחים, והקצוות מתרחקים."}},{kind:"explore",text:"הצלע $AB$ קבועה. גררו את $C$ עד שהזווית $C$, זו שמול $AB$, תהיה ישרה בדיוק.",manip:{kind:"triangle",A:[-5,0],B:[5,0],range:6,start:[-2,3]},answer:[3,4],hint:"כש־$C$ קרוב מדי ל־$AB$ הזווית קהה, וכשהוא רחוק מדי היא חדה. נסו בגובה $4$, והזיזו את $C$ ימינה או שמאלה.",success:"הזווית $C$ ישרה, והיא מול $AB$, הצלע הארוכה במשולש. במשולש ישר־זווית היתר תמיד מול הזווית הישרה."},{kind:"say",fig:c(6,8,{labels:{c:"הצלע הארוכה"},hiHyp:!0}),text:"מכאן המבחן: אם יש זווית ישרה, היא מול הצלע הארוכה, והצלע הזאת היא היתר. לכן משווים את הריבוע של הצלע הארוכה לסכום הריבועים של שתי האחרות."},{kind:"predict",fig:p(11,7,8),text:"משולש עם צלעות $7$, $8$ ו־$11$. $7^2 + 8^2 = 49 + 64 = 113$, ו־$11^2 = 121$. המשולש ישר־זווית?",choices:["כן","לא"],answer:1,why:"$121 \\ne 113$, ולכן אין זווית ישרה. $11$ ארוכה מיתר, כמו בציר שנפתח מעבר ל־$90^\\circ$: הזווית מולה קהה.",wrongWhy:{0:"$113$ ו־$121$ לא שווים. המשולש ישר־זווית רק כשהשוויון מדויק."}},{kind:"explore",text:"ועכשיו $5$, $12$ ו־$13$. בנו משולש ישר־זווית עם הניצבים $5$ ו־$12$, ובדקו אם היתר שלו $13$.",manip:i(5,2),answer:{c:13,a:5,b:12},hint:"השאירו ניצב $5$, וקבעו את השני על $12$. מה יוצא על היתר?",success:"$25 + 144 = 169 = 13^2$. למשולש שבנינו ולמשולש $5, 12, 13$ אותן שלוש צלעות, ולכן הם אותו משולש: גם הוא ישר־זווית."},{kind:"rule",fig:c(3,4,{labels:{a:"a",b:"b",c:"c"},names:["C","_B","_A"]}),text:"המשפט ההפוך: אם ריבוע הצלע הארוכה שווה לסכום ריבועי שתי האחרות, המשולש ישר־זווית, והזווית הישרה מול הצלע הארוכה. אם לא שווה, אין בו זווית ישרה.",display:"a^2 + b^2 = c^2 \\;\\Rightarrow\\; \\sphericalangle C = 90^\\circ",why:"בונים משולש ישר־זווית עם הניצבים $a$ ו־$b$. לפי פיתגורס היתר שלו $\\sqrt{a^2 + b^2} = c$. יש לו אותן שלוש צלעות כמו למשולש שלנו, ומשולשים עם אותן שלוש צלעות חופפים. לכן גם אצלנו הזווית מול $c$ ישרה."},{kind:"predict",fig:c(10,24,{labels:{a:"10",b:"24",c:"26"},right:!1}),text:"צלעות $10$, $26$, $24$. איזו צלע בודקים כיתר?",choices:["$24$, כי היא כתובה אחרונה","$26$, כי היא הארוכה"],answer:1,why:"הסדר שבו כתבו את הצלעות לא משנה. בודקים את הארוכה: $10^2 + 24^2 = 100 + 576 = 676 = 26^2$. המשולש ישר־זווית, והזווית הישרה מול $26$.",wrongWhy:{0:"הסדר שבו כתבו לא משנה. היתר הוא תמיד הצלע הארוכה: $26$."}},{kind:"predict",fig:p(16,9,12),text:"$9$, $12$, $15$ הוא משולש ישר־זווית. ומה עם $9$, $12$, $16$?",choices:["גם ישר־זווית, זה כמעט אותו דבר","לא ישר־זווית"],answer:1,why:"$9^2 + 12^2 = 225$, אבל $16^2 = 256$. השוויון חייב להתקיים בדיוק. סנטימטר אחד יותר, והזווית כבר לא ישרה.",wrongWhy:{0:"כמעט לא מספיק: $225$ ו־$256$ לא שווים. השוויון חייב להיות מדויק."}}],examples:[{problem:"האם משולש שצלעותיו $15$ ס״מ, $8$ ס״מ ו־$17$ ס״מ הוא ישר־זווית? אם כן, מה אורך היתר?",display:"15,\\ 8,\\ 17",answer:17,check:"sqrt(8^2 + 15^2)",fig:p(17,8,15),steps:[{action:"מוצאים את הצלע הארוכה: $17$.",why:"אם יש זווית ישרה, היא מול הצלע הארוכה, והצלע הזאת תהיה היתר.",result:"8 < 15 < 17"},{action:"מחשבים את ריבוע הצלע הארוכה.",why:"זה הצד האחד של המאזניים.",result:"17^2 = 289",calc:{expr:"17^2",value:289}},{action:"מחשבים את סכום הריבועים של שתי האחרות.",why:"זה הצד השני.",result:"8^2 + 15^2 = 64 + 225 = 289",calc:{expr:"8^2 + 15^2",value:289}},{action:"משווים ומסיקים.",why:"שווים, ולכן לפי המשפט ההפוך המשולש ישר־זווית. הזווית הישרה מול $17$, והיא היתר.",result:"8^2 + 15^2 = 17^2",value:"sqrt(8^2 + 15^2)"}]},{problem:"נגר בנה מסגרת ברוחב $40$ ס״מ ובגובה $30$ ס״מ, ומדד את האלכסון: $51$ ס״מ. האם הפינה ישרה? כמה היה צריך להיות האלכסון בפינה ישרה?",answer:50,check:"sqrt(40^2 + 30^2)",fig:b$(40,30,51),steps:[{action:"אם הפינה ישרה, הרוחב, הגובה והאלכסון יוצרים משולש ישר־זווית, והאלכסון הוא היתר.",why:"האלכסון נמצא מול הפינה.",result:"a = 40,\\ b = 30,\\ d = 51"},{action:"מחשבים את סכום הריבועים של הרוחב והגובה.",why:"כך יוצא ריבוע היתר, אם הפינה ישרה.",result:"40^2 + 30^2 = 1600 + 900 = 2500",calc:{expr:"40^2 + 30^2",value:2500}},{action:"מחשבים את ריבוע האלכסון שנמדד.",why:"משווים אותו לסכום.",result:"51^2 = 2601",calc:{expr:"51^2",value:2601}},{action:"משווים: לא שווה, ולכן הפינה לא ישרה.",why:"האלכסון ארוך מדי, ולכן הזווית בפינה מעט גדולה מ־$90^\\circ$, כמו ציר שנפתח יותר מדי.",result:"51^2 - (40^2 + 30^2) = 101",calc:{expr:"51^2 - (40^2 + 30^2)",value:101}},{action:"מוצאים את האלכסון הנכון.",why:"בפינה ישרה האלכסון הוא השורש של הסכום.",result:"\\sqrt{2500} = 50",value:"sqrt(2500)"}]}],together:[{problem:"נבדוק יחד: האם משולש עם הצלעות האלה ישר־זווית?",display:"20,\\ 29,\\ 21",fig:p(29,20,21),steps:[{prompt:"איזו צלע בודקים כיתר?",choices:[{text:"$29$, הארוכה",ok:!0,feedback:"נכון: אם יש זווית ישרה, היא מול הצלע הארוכה."},{text:"$21$, האחרונה ברשימה",ok:!1,feedback:"הסדר ברשימה לא משנה. היתר, אם יש, הוא הצלע הארוכה."},{text:"$20$, הראשונה ברשימה",ok:!1,feedback:"הזווית הישרה, אם יש, נמצאת מול הצלע הארוכה, לא מול הראשונה."}],hints:["במשולש ישר־זווית, איזו צלע הכי ארוכה?","היתר ארוך משני הניצבים, ולכן בודקים את $29$."],done:"בודקים את $29$ כיתר."},{prompt:"מה משווים?",choices:[{text:"$20^2 + 21^2$ מול $29^2$",ok:!0,feedback:"נכון: סכום הריבועים של הקצרות מול ריבוע הארוכה."},{text:"$20 + 21$ מול $29$",ok:!1,feedback:"המבחן הוא על ריבועים. וחוץ מזה, בכל משולש שתי צלעות יחד ארוכות מהשלישית, ולכן $20 + 21$ תמיד יותר מ־$29$."},{text:"$29^2 + 21^2$ מול $20^2$",ok:!1,feedback:"את הריבוע של הצלע הארוכה משווים לסכום של שתי האחרות, לא להפך."}],hints:["מה אומר המשפט על הריבועים של הניצבים ושל היתר?","סכום ריבועי שתי הקצרות מול ריבוע הארוכה: $20^2 + 21^2$ מול $29^2$."],done:"$400 + 441 = 841$, ו־$29^2 = 841$"},{prompt:"יצא $841 = 841$. מה המסקנה?",choices:[{text:"המשולש ישר־זווית, והזווית הישרה מול $29$",ok:!0,feedback:"נכון: זה המשפט ההפוך."},{text:"המשולש ישר־זווית, והזווית הישרה מול $21$",ok:!1,feedback:"הזווית הישרה תמיד מול היתר, הצלע הארוכה."},{text:"אי אפשר לדעת בלי לראות את המשולש",ok:!1,feedback:"זה בדיוק מה שהמשפט ההפוך נותן: מספיק לדעת את שלוש הצלעות."}],hints:["מה אומר המשפט ההפוך כשהשוויון מתקיים?","שווים, ולכן ישר־זווית. הזווית הישרה מול הצלע שבדקנו כיתר."],done:"ישר־זווית, והזווית הישרה מול $29$."}],final:{prompt:"אם המשולש ישר־זווית, כתבו את אורך היתר. אם לא, כתבו $0$.",answer:29,check:"sqrt(20^2 + 21^2)",hints:["המשולש ישר־זווית. איזו צלע היא היתר?","היתר הוא הצלע הארוכה: $29$."]}},{problem:"ועכשיו משולש אחר.",display:"9,\\ 12,\\ 16",fig:p(16,9,12),steps:[{prompt:"מה משווים?",choices:[{text:"$9^2 + 12^2$ מול $16^2$",ok:!0,feedback:"נכון: הצלע הארוכה היא $16$."},{text:"$9 + 12$ מול $16$",ok:!1,misc:"add-legs",feedback:"בכל משולש שתי צלעות יחד ארוכות מהשלישית. המבחן הוא על הריבועים."},{text:"$12^2 + 16^2$ מול $9^2$",ok:!1,feedback:"משווים לריבוע של הצלע הארוכה, לא של הקצרה."}],hints:["איזו צלע יכולה להיות היתר?","הארוכה היא $16$: משווים $9^2 + 12^2$ ל־$16^2$."],done:"$81 + 144 = 225$, ו־$16^2 = 256$"},{prompt:"$225 \\ne 256$. מה המסקנה?",choices:[{text:"לא ישר־זווית: $16$ ארוכה מיתר, והזווית מולה קהה",ok:!0,feedback:"נכון: $16^2$ גדול מהסכום, כמו ציר שנפתח מעבר ל־$90^\\circ$."},{text:"ישר־זווית, כי זה כמעט שווה",ok:!1,feedback:"המבחן דורש שוויון בדיוק. גם הפרש קטן אומר שהזווית לא ישרה."},{text:"ישר־זווית, כי $9$ ו־$12$ כמו במשולש $9, 12, 15$",ok:!1,feedback:"הצלע השלישית כאן $16$, לא $15$, וזה משנה את הזווית."}],hints:["האם השוויון מתקיים?","$256$ גדול מ־$225$: הצלע הארוכה ארוכה מדי בשביל יתר."],done:"לא ישר־זווית."}],final:{prompt:"איזה אורך היה צריך להיות לצלע הארוכה, כדי שהמשולש יהיה ישר־זווית?",answer:15,check:"sqrt(9^2 + 12^2)",hints:["זה היתר של משולש ישר־זווית עם ניצבים $9$ ו־$12$.","$9^2 + 12^2 = 225$, ו־$\\sqrt{225} = 15$."]}}],diag:C$,transfer:S$,misconceptions:[{id:"wrong-hyp",title:"בדקו את הצלע שכתובה אחרונה כאילו היא היתר",cause:"בנוסחה $a^2 + b^2 = c^2$ ה־$c$ כתוב אחרון, וקל לחשוב שהצלע האחרונה ברשימה היא היתר. אבל היתר הוא הצלע הארוכה, בכל מקום שבו היא כתובה.",explain:["נראה שבדקתם צלע שאינה הארוכה בתור יתר.","יתר הוא הצלע שמול הזווית הישרה, והוא תמיד הארוך ביותר. לכן בודקים רק את הצלע הארוכה, בלי קשר לסדר.","למשל $13$, $5$, $12$: $5^2 + 12^2 = 169 = 13^2$. ישר־זווית, למרות ש־$13$ כתובה ראשונה."],remedy:[{kind:"predict",text:"צלעות $25$, $7$, $24$. איזו צלע בודקים כיתר?",choices:["$24$, האחרונה","$25$, הארוכה","$7$, הקצרה"],answer:1,why:"היתר הוא הצלע הארוכה: $7^2 + 24^2 = 49 + 576 = 625 = 25^2$. ישר־זווית, והזווית הישרה מול $25$."},{kind:"explore",text:"צלעות $13$, $5$, $12$. בנו מהן משולש ישר־זווית: בחרו את שני הניצבים כך שהריבוע על היתר יהיה $13^2 = 169$.",manip:i(2,2),answer:{c:13,a:5,b:12},hint:"הניצבים הם שתי הצלעות הקצרות.",success:"הניצבים $5$ ו־$12$, והיתר $13$, הארוכה. לא משנה איפה היא כתובה."}]},{id:"assume-right",title:"קבעו שהמשולש ישר־זווית בלי לבדוק",cause:"לכל משולש יש צלע ארוכה, אבל לא לכל משולש יש זווית ישרה. משפט פיתגורס נכון רק במשולש ישר־זווית, ולכן קודם בודקים.",explain:["נראה שספרתם את כל ארבעת המשולשים כישרי־זווית, בלי לבדוק כל אחד.","לכל משולש יש צלע ארוכה, אבל לא בכל משולש יש זווית ישרה. הצלע הארוכה היא יתר רק אם הריבוע שלה שווה בדיוק לסכום הריבועים של שתי האחרות.","למשל שני משולשים: $6, 8, 10$ ו־$6, 8, 11$. בראשון $36 + 64 = 100 = 10^2$, ולכן הוא ישר־זווית. בשני $11^2 = 121$, ולא $100$, ולכן הוא לא. מתוך השניים רק $1$ ישר־זווית, ולא $2$."],remedy:[{kind:"explore",text:"הצלע $AB$ קבועה. גררו את $C$ למקומות שונים: ברוב המקומות הזווית $C$ לא ישרה. מצאו מקום שבו היא כן ישרה.",manip:{kind:"triangle",A:[-5,0],B:[5,0],range:6,start:[1,2]},answer:[-3,4],hint:"נסו בגובה $4$, והזיזו את $C$ ימינה או שמאלה.",success:"רק במקומות מיוחדים הזווית ישרה. לכן לא מניחים, אלא בודקים."},{kind:"predict",text:"צלעות $6$, $8$, $11$. ישר־זווית?",choices:["כן, $11$ היא היתר","לא: $36 + 64 = 100$, אבל $11^2 = 121$"],answer:1,why:"השוויון לא מתקיים, ולכן אין זווית ישרה. $11$ ארוכה מיתר: הזווית מולה קהה."}]},{id:"add-legs",title:"השוו את סכום הצלעות, במקום את סכום הריבועים",cause:"בדקו אם $a + b = c$. אבל בכל משולש שתי צלעות יחד ארוכות מהשלישית, ולכן זה לא קורה אף פעם. המבחן הוא על הריבועים.",explain:["נראה שהשוויתם את הצלעות עצמן, בלי לרבע.","$3 + 4 = 7$, ולא $5$. ובכל זאת המשולש $3, 4, 5$ ישר־זווית, כי $9 + 16 = 25$.","משווים שטחים של ריבועים: $a^2 + b^2$ מול $c^2$."],remedy:[{kind:"predict",text:"האם המשולש $3, 4, 5$ ישר־זווית?",choices:["לא, כי $3 + 4 \\ne 5$","כן, כי $9 + 16 = 25$"],answer:1,why:'בכל משולש $a + b$ ארוך מ־$c$, ולכן השוואת אורכים תמיד תגיד "לא". המבחן הוא על הריבועים.'},{kind:"explore",text:"בנו משולש ישר־זווית שהריבועים על הניצבים שלו יחד הם $25$.",manip:i(2,2),answer:{c:5,a:3,b:4},hint:"נסו ניצבים $3$ ו־$4$.",success:"$9 + 16 = 25$: הצלעות $3, 4, 5$ נותנות משולש ישר־זווית, למרות ש־$3 + 4 \\ne 5$."}],prereq:"pyth:1"}]},k=$=>E[$.k].per,u=$=>String(Math.round($*1e6)/1e6),P=$=>($.ask===0?$.c:$.ask===1?$.big:$.small)/k($),Z=$=>A(P($)),w=$=>$.ask===0?$.big*$.big+$.small*$.small:$.c*$.c-R($)**2,N=$=>v(w($))?`= ${u(Math.sqrt(w($))/k($))}`:`\\approx ${O(Math.sqrt(w($))/k($))}`,R=$=>$.ask===1?$.small:$.big,D=$=>{const e=$();return e<.4?0:e<.75?1:2},$$=($,e,t)=>{const[s,a,r]=f($,t);return{k:e,ask:D($),c:r,big:Math.max(s,a),small:Math.min(s,a)}},e$=($,e)=>{const t=D($);for(;;){if(t===0){const d=o($,5,24),h=o($,2,d-1);if(!v(d*d+h*h))return{k:e,ask:t,c:Math.sqrt(d*d+h*h),big:d,small:h};continue}const s=o($,8,30),a=o($,Math.ceil(s/3),s-1),r=s*s-a*a;if(v(r))continue;const n=Math.sqrt(r);if(t===1&&n>a)return{k:e,ask:t,c:s,big:n,small:a};if(t===2&&n<a)return{k:e,ask:t,c:s,big:a,small:n}}},Q={"add-legs":$=>$.ask===0?($.big+$.small)/k($):null,"no-root":$=>w($)/k($)**2,"wrong-hyp":$=>$.ask===0?Math.sqrt($.big*$.big-$.small*$.small)/k($):null,"add-not-sub":$=>$.ask===0?null:Math.sqrt($.c*$.c+R($)**2)/k($),"subtract-sides":$=>$.ask===0?null:($.c-R($))/k($)},E=[{hyp:"הסולם",angle:"הקיר והרצפה",unit:"מטר",per:10},{hyp:"האלכסון",angle:"הרוחב והגובה של המסך",unit:"אינץ׳",per:1},{hyp:"הכבל",angle:"העמוד והקרקע",unit:"מטר",per:1}],t$=$=>{const e=E[$.k],t=n=>u(n/e.per),s=n=>u(n/e.per**2),a=`הזווית הישרה היא בין ${e.angle}, ו${e.hyp} מולה: ${e.hyp} הוא היתר.`;if($.ask===0)return[a,`חסר היתר, ולכן מחברים ריבועים: $${t($.big)}^2 + ${t($.small)}^2 = ${s($.big**2)} + ${s($.small**2)} = ${s(w($))}$.`,`מוציאים שורש: $\\sqrt{${s(w($))}} ${N($)}$ ${e.unit}.`];const r=R($);return[a,`חסר ניצב, ולכן מחסרים מריבוע היתר: $${t($.c)}^2 - ${t(r)}^2 = ${s($.c**2)} - ${s(r**2)} = ${s(w($))}$.`,`מוציאים שורש: $\\sqrt{${s(w($))}} ${N($)}$ ${e.unit}.`]},s$=$=>{const e=E[$.k];return $.ask===0?`${e.hyp} מול הזווית הישרה, והוא מה שחסר: מחברים את ריבועי שני הניצבים ומוציאים שורש.`:`${e.hyp} הוא היתר, והוא נתון. מה שחסר הוא ניצב: מחסרים מריבוע היתר את ריבוע הניצב הידוע.`},R$={params:$=>{for(;;){const e=$()<.5?$$($,0,M.filter(t=>t[2]<=26)):e$($,0);if(e.c>=12&&Object.values(Q).every(t=>{const s=t(e);return s==null||Math.abs(s-P(e))>=.1}))return e}},text:$=>[`סולם נשען על קיר ומגיע לגובה $${u($.big/10)}$ מטר. רגל הסולם רחוקה $${u($.small/10)}$ מטר מהקיר. מה אורך הסולם?`,`סולם באורך $${u($.c/10)}$ מטר נשען על קיר. רגל הסולם רחוקה $${u($.small/10)}$ מטר מהקיר. לאיזה גובה על הקיר מגיע הסולם?`,`סולם באורך $${u($.c/10)}$ מטר נשען על קיר ומגיע לגובה $${u($.big/10)}$ מטר. כמה רחוקה רגל הסולם מהקיר?`][$.ask]+` ${x}`,answer:Z,exact:P,bugs:Q,solution:t$,hint:s$,unit:"מטר"},L$={params:$=>{if($()<.5){const e=o($,2,10);return{k:1,ask:D($),c:5*e,big:4*e,small:3*e}}return $()<.5?$$($,2,M.filter(e=>e[2]<=30)):e$($,2)},text:$=>($.k===1?[`למסך רוחב $${$.big}$ אינץ׳ וגובה $${$.small}$ אינץ׳. הגודל של מסך הוא אורך האלכסון שלו. מה הגודל של המסך הזה?`,`מסך בגודל $${$.c}$ אינץ׳ (זה אורך האלכסון שלו), וגובהו $${$.small}$ אינץ׳. מה הרוחב שלו?`,`מסך בגודל $${$.c}$ אינץ׳ (זה אורך האלכסון שלו), ורוחבו $${$.big}$ אינץ׳. מה הגובה שלו?`]:[`עמוד בגובה $${$.big}$ מטר מוחזק בכבל מתוח מראש העמוד אל נקודה בקרקע, $${$.small}$ מטר מבסיס העמוד. מה אורך הכבל?`,`כבל באורך $${$.c}$ מטר מתוח מראש עמוד אל נקודה בקרקע, $${$.small}$ מטר מבסיס העמוד. מה גובה העמוד?`,`כבל באורך $${$.c}$ מטר מתוח מראש עמוד בגובה $${$.big}$ מטר אל נקודה בקרקע. כמה רחוקה הנקודה מבסיס העמוד?`])[$.ask]+` ${x}`,answer:Z,exact:P,bugs:Q,solution:t$,hint:s$},Q$={skill:"pyth:4",topic:"pyth",level:4,title:"שאלה מילולית",objectives:["למצוא בסיפור את המשולש ישר־הזווית: איפה הזווית הישרה, ומי הצלע שמולה.","להחליט מה חסר, יתר או ניצב, ולפי זה לחבר או לחסר ריבועים.","לבדוק שהתשובה הגיונית בתוך הסיפור."],idea:"בשאלה מילולית המשולש מסתתר בסיפור. קודם מוצאים את הזווית הישרה (קיר ורצפה, פינה של מסך), ואז את היתר שמולה. רק אחר כך מחליטים: חסר יתר, מחברים ריבועים; חסר ניצב, מחסרים.",why:["משפט פיתגורס מדבר על תפקידים: שני ניצבים ויתר. בתרגיל עם ציור התפקידים מסומנים, ובסיפור צריך לגלות אותם לבד.","קיר עומד ניצב לרצפה, ופינה של מלבן היא זווית ישרה. לכן הסולם, או האלכסון של המסך, נמצאים מול הזווית הישרה: הם היתר.","אם מבלבלים תפקידים, מחברים במקום לחסר או להפך, והתשובה יוצאת לא הגיונית: סולם קצר מהגובה שהוא מגיע אליו, או ניצב ארוך מהיתר."],alt:["תמיד ציירו סקיצה: קו לקיר, קו לרצפה, וריבוע קטן בפינה ביניהם. הקו שמחבר באלכסון את הקצוות הוא היתר.","שאלו: מה מחבר באלכסון בין שני קווים שנפגשים בזווית ישרה? הסולם בין הקיר לרצפה, החוט של עפיפון בין הקרקע לגובה, האלכסון בין הרוחב לגובה. זה תמיד היתר, והוא הארוך ביותר."],discover:[{kind:"say",mood:"happy",fig:B({right:!1}),text:"בשאלה מילולית אין ציור מוכן. התפקיד הראשון שלנו: למצוא את המשולש ישר־הזווית שמסתתר בסיפור."},{kind:"predict",fig:B({right:!1}),text:"סולם נשען על קיר. איפה הזווית הישרה?",choices:["בין הסולם לקיר","בין הקיר לרצפה","בין הסולם לרצפה"],answer:1,why:"קיר עומד זקוף על הרצפה, וביניהם $90^\\circ$. הסולם נשען באלכסון, ולכן הזוויות שלו עם הקיר ועם הרצפה לא ישרות.",wrongWhy:{0:"הסולם נשען באלכסון, אז הזווית שלו עם הקיר לא ישרה. הישרה בין הקיר לרצפה.",2:"הסולם נוטה, אז הזווית שלו עם הרצפה לא ישרה. הישרה בין הקיר לרצפה."}},{kind:"predict",fig:B(),text:"אז מי היתר?",choices:["הסולם","הקיר, עד המקום שהסולם נוגע בו","המרחק מרגל הסולם לקיר"],answer:0,why:"היתר הוא הצלע שמול הזווית הישרה: הסולם, שמחבר באלכסון את הקיר והרצפה.",wrongWhy:{1:"הקיר הוא צלע של הזווית הישרה, ולכן ניצב. היתר מולה: הסולם.",2:"גם הרצפה היא צלע של הזווית הישרה, ולכן ניצב. היתר מולה: הסולם."}},{kind:"explore",text:"סולם כבאים באורך $13$ מטר, ורגלו $5$ מטר מהבניין. בנו את המשולש: המרחק מהבניין הוא ניצב אחד, והסולם הוא היתר.",manip:i(5,2),answer:{c:13,a:5,b:12},hint:"השאירו ניצב $5$, ושנו את השני, הגובה, עד שהריבוע על היתר יהיה $13^2 = 169$.",success:"הסולם מגיע לגובה $12$ מטר: $5^2 + 12^2 = 13^2$. הגובה הוא ניצב, והסולם הוא היתר."},{kind:"predict",fig:B({labels:{len:"10",wall:"8",foot:"?"}}),text:"סולם באורך $10$ מטר מגיע לגובה $8$ מטר על הקיר. כמה רחוקה רגל הסולם מהקיר? מה חסר כאן?",choices:["היתר, ולכן מחברים ריבועים","ניצב, ולכן מחסרים ריבועים"],answer:1,why:"הסולם, היתר, נתון. חסר המרחק על הרצפה, וזה ניצב. $10^2 - 8^2 = 36$, והמרחק $6$ מטר.",wrongWhy:{0:"היתר הוא הסולם, והוא נתון: $10$. חסר המרחק על הרצפה, וזה ניצב."}},{kind:"say",fig:C(8,4.5),text:"עוד משולש נסתר: מסך. הגודל של מסך נמדד לפי האלכסון שלו. הרוחב והגובה נפגשים בפינה בזווית ישרה, והאלכסון מולה."},{kind:"predict",fig:C(8,6,{width:"80",height:"60",diag:"?"}),text:"מסך ברוחב $80$ ס״מ ובגובה $60$ ס״מ. מה אורך האלכסון?",choices:["$140$ ס״מ","$100$ ס״מ","$20$ ס״מ"],answer:1,why:"$80^2 + 60^2 = 6400 + 3600 = 10000$, ו־$\\sqrt{10000} = 100$.",wrongWhy:{0:"$140$ הוא הדרך לאורך שתי הצלעות של המסך. האלכסון הוא קיצור דרך.",2:"האלכסון מול הזווית הישרה, ולכן הוא הארוך ביותר. מחברים ריבועים, לא מחסרים."}},{kind:"rule",fig:c(3,4,{labels:{a:"ניצב",b:"ניצב",c:"יתר"},hiHyp:!0}),text:"בשאלה מילולית: מסמנים את הזווית הישרה, ומוצאים את היתר שמולה. חסר היתר: מחברים ריבועים. חסר ניצב: מחסרים מריבוע היתר. בסוף מוציאים שורש ובודקים שהתשובה הגיונית.",why:"משפט פיתגורס תלוי בתפקידים: מי ניצב ומי יתר. בסיפור אף אחד לא כותב $a$, $b$ ו־$c$, ולכן מוצאים אותם לפי הזווית הישרה."},{kind:"predict",fig:l$(12,35),text:"אומגה: כבל מתוח מראש עמוד בגובה $12$ מטר אל נקודה בקרקע, $35$ מטר מבסיס העמוד. מה אורך הכבל?",choices:["$37$ מטר","$47$ מטר","$23$ מטר"],answer:0,why:"הכבל מחבר את ראש העמוד לקרקע, מול הזווית הישרה שבין העמוד לקרקע: הוא היתר. $12^2 + 35^2 = 144 + 1225 = 1369$, ו־$\\sqrt{1369} = 37$.",wrongWhy:{1:"$47$ הוא $12 + 35$. מחברים ריבועים, לא אורכים.",2:"$23$ הוא $35 - 12$. הכבל הוא היתר, ולכן הוא ארוך משתי הצלעות האחרות."}},{kind:"say",fig:B({labels:{len:"סולם",wall:"גובה"}}),text:"ובסוף בודקים בשכל: סולם ארוך מהגובה שהוא מגיע אליו, ואלכסון של מסך ארוך מהרוחב שלו. תשובה שלא מסתדרת עם זה אומרת שהתפקידים התבלבלו."}],examples:[{problem:"סולם באורך $2.6$ מטר נשען על קיר. רגל הסולם רחוקה מטר אחד מהקיר. לאיזה גובה על הקיר מגיע הסולם?",answer:2.4,check:"sqrt(2.6^2 - 1^2)",fig:y$(1,2.4,{len:"2.6",foot:"1",wall:"?"}),steps:[{action:"מציירים: קיר, רצפה וסולם. הזווית הישרה בין הקיר לרצפה.",why:"הסולם מולה, ולכן הוא היתר. הגובה והמרחק מהקיר הם הניצבים.",result:"c = 2.6,\\ a = 1,\\ h = ?"},{action:"הגובה הוא ניצב, ולכן מחסרים.",why:"היתר נתון: הריבוע עליו הוא השלם.",result:"h^2 = 2.6^2 - 1^2 = 6.76 - 1 = 5.76",calc:{expr:"2.6^2 - 1^2",value:5.76}},{action:"מוציאים שורש.",why:"מהשטח לאורך.",result:"h = \\sqrt{5.76} = 2.4",value:"sqrt(5.76)"},{action:"בודקים שהתשובה הגיונית.",why:"הסולם ארוך מהגובה שהוא מגיע אליו, כמו שצריך.",result:"2.4 < 2.6"}]},{problem:"מסך בגודל $125$ ס״מ: זה אורך האלכסון שלו. גובה המסך $75$ ס״מ. מה הרוחב שלו?",answer:100,check:"sqrt(125^2 - 75^2)",fig:C(100,75,{width:"?",height:"75",diag:"125"}),steps:[{action:"מוצאים את הזווית הישרה: בפינה של המסך, בין הרוחב לגובה.",why:"האלכסון מול הפינה, ולכן הוא היתר. הרוחב הוא ניצב.",result:"c = 125,\\ a = 75,\\ w = ?"},{action:"חסר ניצב, ולכן מחסרים.",why:"הריבוע על האלכסון הוא השלם.",result:"w^2 = 125^2 - 75^2 = 15625 - 5625 = 10000",calc:{expr:"125^2 - 75^2",value:1e4}},{action:"מוציאים שורש.",why:"$100 \\cdot 100 = 10000$.",result:"w = \\sqrt{10000} = 100",value:"sqrt(10000)"},{action:"בודקים.",why:"הרוחב קצר מהאלכסון, והמשפט מתקיים.",result:"75^2 + 100^2 = 5625 + 10000 = 15625 = 125^2",calc:{expr:"75^2 + 100^2",value:15625}}]}],together:[{problem:"החוט של העפיפון של נועה באורך $17$ מטר, והוא מתוח. העפיפון נמצא בדיוק מעל נקודה שרחוקה $8$ מטר מנועה. בכמה מטרים העפיפון גבוה מהיד שלה?",fig:x$(17,8),steps:[{prompt:"איפה הזווית הישרה?",choices:[{text:"בין הקו האנכי מהעפיפון למטה לבין הקו האופקי מהיד",ok:!0,feedback:"נכון: קו אנכי וקו אופקי נפגשים בזווית ישרה."},{text:"בין החוט לקרקע",ok:!1,feedback:"החוט עולה באלכסון, ולכן הזווית שלו עם הקרקע לא ישרה."},{text:"אין כאן זווית ישרה",ok:!1,feedback:'"בדיוק מעל" אומר קו אנכי, והוא ניצב לקרקע.'}],hints:['מה פירוש "העפיפון בדיוק מעל נקודה"?',"מהעפיפון יורד קו אנכי לנקודה, והוא פוגש את הקו האופקי מהיד בזווית ישרה."],done:"הזווית הישרה מתחת לעפיפון."},{prompt:"מי היתר?",choices:[{text:"החוט, $17$ מטר",ok:!0,feedback:"נכון: הוא מול הזווית הישרה."},{text:"המרחק על הקרקע, $8$ מטר",ok:!1,feedback:"המרחק על הקרקע הוא אחת הצלעות של הזווית הישרה, כלומר ניצב."},{text:"הגובה של העפיפון",ok:!1,feedback:"הגובה הוא הקו האנכי, צלע של הזווית הישרה: ניצב."}],hints:["איזו צלע לא נוגעת בזווית הישרה?","החוט מחבר את היד לעפיפון באלכסון, מול הזווית הישרה."],done:"החוט הוא היתר."},{prompt:"מה מחשבים?",choices:[{text:"$17^2 - 8^2$",ok:!0,feedback:"נכון: חסר ניצב, ולכן מחסרים מריבוע היתר."},{text:"$17^2 + 8^2$",ok:!1,misc:"add-not-sub",feedback:"מחברים כשמחפשים את היתר. כאן היתר, החוט, נתון."},{text:"$17 - 8$",ok:!1,misc:"subtract-sides",feedback:"מחסרים ריבועים, לא אורכים."}],hints:["מה חסר: יתר או ניצב?","הגובה הוא ניצב: $17^2 - 8^2 = 289 - 64$."],done:"$h^2 = 289 - 64 = 225$"}],final:{prompt:"בכמה מטרים העפיפון גבוה מהיד?",answer:15,check:"sqrt(17^2 - 8^2)",hints:["איזה מספר כפול עצמו נותן $225$?","$15 \\cdot 15 = 225$."]}},{problem:"למסך רוחב $96$ ס״מ וגובה $72$ ס״מ. מה אורך האלכסון שלו?",fig:C(96,72,{width:"96",height:"72",diag:"?"}),steps:[{prompt:"מה התפקיד של האלכסון?",choices:[{text:"יתר: הוא מול הזווית הישרה שבפינת המסך",ok:!0,feedback:"נכון, ולכן מחברים ריבועים."},{text:"ניצב",ok:!1,feedback:"הניצבים הם הרוחב והגובה, שנפגשים בפינה. האלכסון מולה."}],hints:["איפה הזווית הישרה במסך?","בפינה, בין הרוחב לגובה. האלכסון מולה."],done:"האלכסון הוא היתר: $d^2 = 96^2 + 72^2$."}],final:{prompt:"מה אורך האלכסון, בס״מ?",answer:120,check:"sqrt(96^2 + 72^2)",hints:["$96^2 + 72^2 = 9216 + 5184 = 14400$.","$\\sqrt{14400} = 120$, כי $12^2 = 144$."]}}],diag:R$,transfer:L$,misconceptions:[{id:"add-legs",title:"חיברו את שתי הצלעות הנתונות, בלי לרבע",cause:"בסיפור קל לחבר את מה שנתון. אבל היתר הוא קיצור דרך, ומשפט פיתגורס מחבר ריבועים.",explain:["נראה שחיברתם את שתי הצלעות הנתונות, למשל את הגובה ואת המרחק מהקיר.","זו הדרך לאורך הקיר ואז לאורך הרצפה. הסולם הולך ישר, ולכן הוא קצר יותר. כך גם כבל, או אלכסון של מסך.","מחברים ריבועים ומוציאים שורש: גובה $12$ ומרחק $5$ נותנים סולם $\\sqrt{144 + 25} = 13$."],remedy:[{kind:"predict",text:"הסולם מגיע לגובה $12$, ורגלו $5$ מהקיר. האם הסולם באורך $17$?",choices:["כן","לא, הוא קצר יותר"],answer:1,why:"$12 + 5$ הוא הדרך לאורך הקיר והרצפה. הסולם הוא קיצור דרך: $\\sqrt{144 + 25} = 13$."},{kind:"explore",text:"בנו את המשולש של הסולם: רגל $5$ מהקיר וגובה $12$. כמה יוצא על היתר, הסולם?",manip:i(5,2),answer:{c:13,a:5,b:12},hint:"קבעו ניצבים $5$ ו־$12$.",success:"על הסולם $25 + 144 = 169$, ולכן הסולם $13$, לא $17$."}],prereq:"pyth:1"},{id:"no-root",title:"עצרו בריבוע ושכחו להוציא שורש",cause:"בסוף החישוב יוצא השטח של ריבוע, והשאלה בסיפור היא על אורך.",explain:["החשבון היה נכון, אבל המספר שיצא הוא שטח.","בדיקת שכל עוזרת: מסך של $2500$ ס״מ באלכסון הוא $25$ מטר. זה לא נכנס לסלון. השורש, $50$ ס״מ, כן הגיוני."],remedy:[{kind:"predict",text:"לאלכסון של מסך יצא $d^2 = 2500$. מה אורך האלכסון?",choices:["$2500$ ס״מ","$50$ ס״מ"],answer:1,why:"$2500$ הוא השטח של הריבוע על האלכסון. האורך הוא $\\sqrt{2500} = 50$, כי $50 \\cdot 50 = 2500$."},{kind:"explore",text:"בנו משולש שהריבוע על היתר שלו בשטח $100$. כמה ארוך היתר?",manip:i(2,2),answer:{c:10,a:6,b:8},hint:"נסו ניצבים $6$ ו־$8$.",success:"שטח $100$ על היתר, והיתר עצמו $10$. בסוף תמיד חוזרים משטח לאורך."}],prereq:"pyth:1"},{id:"wrong-hyp",title:"בחרו כיתר את הצלע הנתונה הארוכה, במקום את הצלע שמול הזווית הישרה",cause:"כשהיתר הוא מה שחסר, הוא לא מופיע בסיפור כמספר. קל לחשוב שהמספר הגדול שנתון הוא היתר, ולחסר.",explain:["נראה שחיסרתם, כאילו אחת הצלעות הנתונות היא היתר.","היתר הוא הצלע שמול הזווית הישרה. בסולם, הזווית הישרה בין הקיר לרצפה, ולכן היתר הוא הסולם, גם כשאורכו הוא מה שמחפשים.","מכאן: חסר הסולם, ולכן מחברים את ריבועי הגובה והמרחק."],remedy:[{kind:"predict",text:"הסולם מגיע לגובה $12$ מטר על הקיר, ורגלו $5$ מטר מהקיר. מי היתר?",choices:["הגובה, $12$, כי הוא המספר הגדול","הסולם, שאורכו עוד לא ידוע"],answer:1,why:"היתר מול הזווית הישרה, שבין הקיר לרצפה. זה הסולם. מחברים: $12^2 + 5^2 = 169$, והסולם $13$ מטר."},{kind:"explore",text:"בנו את המשולש: הרצפה $5$ והקיר $12$ הם הניצבים. מה יוצא על היתר, הסולם?",manip:i(5,5),answer:{c:13,a:5,b:12},hint:"קבעו ניצבים $5$ ו־$12$.",success:"הסולם $13$, ארוך מהגובה. אילו הגובה היה היתר, הסולם היה יוצא קצר ממנו."}]},{id:"add-not-sub",title:"חיברו ריבועים כשהיתר נתון וחסר ניצב",cause:"הסולם (או הכבל, או האלכסון) הוא היתר, והוא כבר נתון. מה שחסר הוא ניצב, ולכן מחסרים.",explain:["נראה שחיברתם את ריבוע היתר (הסולם, הכבל או האלכסון) עם ריבוע הצלע השנייה.","היתר כבר נתון: הריבוע עליו הוא השלם. הצלע החסרה היא ניצב, חלק מהשלם, ולכן מחסרים.","בדיקת שכל: גובה שיוצא ארוך מהסולם לא ייתכן. סולם לא מגיע גבוה יותר מהאורך שלו."],remedy:[{kind:"predict",text:"סולם באורך $10$ מטר, ורגלו $6$ מטר מהקיר. מחפשים את הגובה. מה הגובה במשולש: היתר או ניצב?",choices:["היתר, ולכן מחברים","ניצב, ולכן מחסרים"],answer:1,why:"הסולם הוא היתר, והוא נתון. הגובה הוא ניצב: $10^2 - 6^2 = 64$, והגובה $8$ מטר."},{kind:"explore",text:"רגל הסולם $6$ מהקיר, והסולם $10$. מצאו את הגובה: שנו את הניצב השני עד שהיתר יהיה $10$.",manip:i(6,2),answer:{c:10,a:6,b:8},hint:"השאירו ניצב $6$. הריבוע על היתר צריך להיות $100$.",success:"הגובה $8$, קצר מהסולם: $100 - 36 = 64$."}],prereq:"pyth:2"},{id:"subtract-sides",title:"חיסרו את האורכים בלי לרבע",cause:"הכיוון נכון, כי חסר ניצב, אבל משפט פיתגורס מחסר שטחים של ריבועים, לא אורכים.",explain:["נכון לחסר כשחסר ניצב. אבל מחסרים את הריבועים.","סולם $25$ ורגל $7$: $25 - 7 = 18$, אבל $7^2 + 18^2 = 373$, ולא $625$. נכון: $625 - 49 = 576$, והגובה $24$."],remedy:[{kind:"predict",text:"סולם באורך $13$ ורגלו $5$ מהקיר. האם הוא מגיע לגובה $13 - 5 = 8$?",choices:["כן","לא"],answer:1,why:"$5^2 + 8^2 = 89$, ולא $169$. מחסרים ריבועים: $169 - 25 = 144$, והגובה $12$."},{kind:"explore",text:"סולם $13$ ורגל $5$. מתחילים מגובה $8$: ראו מה יוצא על היתר, ותקנו את הגובה.",manip:i(5,8),answer:{c:13,a:5,b:12},hint:"עם גובה $8$ הסולם יוצא קצר מדי. הגדילו את הגובה עד שעל היתר יהיה $169$.",success:"הגובה $12$: $25 + 144 = 169$."}]}]},j$=M.filter($=>$[1]<=12);function a$($){for(;;){const[e,t]=$()<.5?f($,j$):[o($,1,9),o($,1,9)],[s,a]=$()<.5?[e,t]:[t,e],r=o($,-6,6),n=o($,-6,6),d=r+($()<.5?s:-s),h=n+($()<.5?a:-a);if(Math.abs(d)<=12&&Math.abs(h)<=12)return{x1:r,y1:n,x2:d,y2:h}}}const m=$=>Math.abs($.x2-$.x1),q=$=>Math.abs($.y2-$.y1),j=$=>m($)**2+q($)**2,_=$=>Math.sqrt(j($)),c$=$=>A(_($)),z=($,e)=>Math.abs(Math.abs(e)-Math.abs($)),i$={"add-legs":$=>m($)+q($),"no-root":$=>m($)**2+q($)**2,"coord-diff":$=>{const e=z($.x1,$.x2),t=z($.y1,$.y2);return e===m($)&&t===q($)?null:Math.hypot(e,t)}},r$=$=>[`הניצב האופקי הוא ההפרש ב־$x$: $|${l($.x2)} - ${l($.x1,!0)}| = ${m($)}$.`,`הניצב האנכי הוא ההפרש ב־$y$: $|${l($.y2)} - ${l($.y1,!0)}| = ${q($)}$.`,`$d = \\sqrt{${m($)}^2 + ${q($)}^2} = \\sqrt{${j($)}} ${g(j($))}$`],n$=$=>`השלימו משולש ישר־זווית: ניצב אחד הוא כמה זזים ב־$x$, מ־$${l($.x1)}$ עד $${l($.x2)}$, והשני כמה זזים ב־$y$.`,O$={params:a$,text:()=>`מה המרחק בין הנקודות $A$ ו־$B$? ${x}`,display:$=>`A(${l($.x1)}, ${l($.y1)}) \\qquad B(${l($.x2)}, ${l($.y2)})`,answer:c$,exact:_,bugs:i$,solution:r$,hint:n$,unit:"יחידות"},H$={params:a$,text:()=>`שני רחפנים מרחפים באותו גובה. המיקום של כל אחד במפה, בקילומטרים, כתוב בטבלה. מה המרחק ביניהם בקו ישר, בקילומטרים? ${x}`,display:$=>`\\begin{array}{c|c|c} & x & y \\\\ \\hline A & ${l($.x1)} & ${l($.y1)} \\\\ B & ${l($.x2)} & ${l($.y2)} \\end{array}`,answer:c$,exact:_,bugs:i$,solution:r$,hint:$=>`במפה כמו במערכת צירים: ההפרש ב־$x$ וההפרש ב־$y$ הם הניצבים, והמרחק בקו ישר הוא היתר. ${n$($)}`},T$={skill:"pyth:5",topic:"pyth",level:5,title:"מרחק בין נקודות",objectives:["להשלים לקטע בין שתי נקודות משולש ישר־זווית, עם קו אופקי וקו אנכי.","לחשב את הניצבים כהפרשים בין השיעורים, גם עם מספרים שליליים.","לחשב את המרחק בעזרת משפט פיתגורס."],idea:"כל קטע אלכסוני ברשת הוא יתר של משולש ישר־זווית: ניצב אחד אופקי, באורך ההפרש ב־$x$, וניצב אחד אנכי, באורך ההפרש ב־$y$. המרחק הוא השורש של סכום הריבועים שלהם.",why:["קו אופקי וקו אנכי נפגשים בזווית ישרה, בדיוק כמו הצירים. לכן הם ניצבים, והקטע שמחבר את שתי הנקודות הוא היתר.","אורך של קו אופקי הוא כמה צעדים זזים ב־$x$: ההפרש בין שיעורי ה־$x$. אורך של קו אנכי הוא ההפרש בין שיעורי ה־$y$.","אם מתחילים מהנקודה השנייה, ההפרש יוצא שלילי, אבל אחרי שמרבעים הסימן נעלם. לכן לא משנה מאיזו נקודה מתחילים."],alt:["חשבו על מפה של עיר עם רחובות ישרים. ברחובות הולכים ימינה ואז למעלה, ההפרש ב־$x$ ועוד ההפרש ב־$y$. ציפור עפה בקו ישר, לאורך היתר, וזה קצר יותר.","אפשר לסמן מלבן שהקטע הוא האלכסון שלו, עם צלעות על קווי הרשת. הצלעות של המלבן הן ההפרשים, ואת האלכסון מחשבים כמו אלכסון של מסך."],discover:[{kind:"say",fig:{type:"coord",range:6,segments:[[[-5,4],[-1,4]],[[3,1],[3,5]],[[-4,-5],[-1,-1]]],anim:!0},mood:"happy",text:"במערכת צירים קל למדוד קטע אופקי או אנכי: סופרים משבצות. אבל מה עושים עם קטע אלכסוני?"},{kind:"predict",fig:{type:"coord",range:6,points:[{label:"A",x:1,y:2},{label:"B",x:5,y:2}],segments:[[[1,2],[5,2]]]},text:"מה המרחק בין $A(1, 2)$ ל־$B(5, 2)$?",choices:["$4$","$6$","$3$"],answer:0,why:"לשתי הנקודות אותו $y$, ולכן הן באותה שורה. המרחק הוא ההפרש ב־$x$: $5 - 1 = 4$.",wrongWhy:{1:"$6$ הוא $5 + 1$. המרחק הוא הפרש: $5 - 1$.",2:"ספרו צעדים, לא נקודות: מ־$1$ עד $5$ יש $4$ צעדים."}},{kind:"explore",text:"הקטע $AB$ הוא האלכסון של המלבן $ADBC$, שהצלעות שלו על קווי הרשת. שימו את הקודקוד $C$ שמשלים את המלבן: מתחת ל־$B$, ובשורה של $A$.",manip:{kind:"plot",range:6,label:"C",shape:[{label:"B",at:[4,5]},{label:"D",at:[1,5]},{label:"A",at:[1,1]}]},answer:[4,1],hint:"$C$ באותו טור של $B$, כלומר $x = 4$, ובאותה שורה של $A$, כלומר $y = 1$.",success:"המשולש $ACB$ ישר־זווית ב־$C$: $AC$ אופקי ו־$CB$ אנכי. הקטע $AB$ הוא היתר שלו."},{kind:"predict",fig:{type:"coord",range:6,points:[{label:"A",x:1,y:1},{label:"B",x:4,y:5},{label:"C",x:4,y:1}],segments:[[[1,1],[4,1]],[[4,1],[4,5]]],helper:[[1,1],[4,5]]},text:"מה אורכי הניצבים $AC$ ו־$CB$?",choices:["$AC = 3$, $CB = 4$","$AC = 4$, $CB = 5$","$AC = 1$, $CB = 4$"],answer:0,why:"$AC$ אופקי: ההפרש ב־$x$, $4 - 1 = 3$. $CB$ אנכי: ההפרש ב־$y$, $5 - 1 = 4$.",wrongWhy:{1:"$4$ ו־$5$ הם השיעורים של $B$. אורך הוא הפרש: כמה צעדים מ־$A$.",2:"$1$ הוא השיעור של $A$, לא אורך. $AC$ הולך מ־$x = 1$ עד $x = 4$."}},{kind:"predict",fig:{type:"coord",range:6,points:[{label:"A",x:1,y:1},{label:"B",x:4,y:5}],polygon:[[1,1],[4,1],[4,5]],segments:[[[1,1],[4,5]]]},text:"אז מה המרחק $AB$?",choices:["$7$","$5$","$25$"],answer:1,why:"$AB$ הוא היתר: $3^2 + 4^2 = 25$, ו־$\\sqrt{25} = 5$.",wrongWhy:{0:"$7$ היא הדרך במדרגות: $3$ ימינה ו־$4$ למעלה. הקו הישר קצר יותר.",2:"$25$ הוא השטח של הריבוע על $AB$. האורך הוא השורש."}},{kind:"predict",fig:{type:"coord",range:6,points:[{label:"A",x:-3,y:2},{label:"B",x:3,y:-6}],segments:[[[-3,2],[3,-6]]],helper:[[-3,2],[3,2],[3,-6]]},text:"מ־$A(-3, 2)$ ל־$B(3, -6)$: מה אורך הניצב האנכי?",choices:["$4$","$8$","$-8$"],answer:1,why:"מ־$2$ יורדים עד $-6$: $2$ צעדים עד האפס, ועוד $6$ אחריו. ביחד $8$. בחשבון: $2 - (-6) = 8$.",wrongWhy:{0:"$4$ יוצא מ־$6 - 2$, בלי הסימנים. כשעוברים את האפס, הצעדים משני הצדדים מצטרפים.",2:"אורך של צלע תמיד חיובי. ההפרש $-6 - 2 = -8$ אומר רק שיורדים."}},{kind:"explore",text:"מ־$A(-3, 2)$ ל־$B(3, -6)$ הניצב האופקי $6$ והאנכי $8$. בנו את המשולש, ומצאו את המרחק.",manip:i(2,2),answer:{c:10,a:6,b:8},hint:"קבעו ניצבים $6$ ו־$8$.",success:"על היתר $36 + 64 = 100$, ולכן $AB = \\sqrt{100} = 10$."},{kind:"rule",fig:{type:"coord",range:6,polygon:[[-3,2],[3,2],[3,-6]],segments:[[[-3,2],[3,-6]]]},text:"המרחק בין שתי נקודות: הניצבים הם ההפרש ב־$x$ וההפרש ב־$y$, והמרחק הוא היתר.",display:"d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}",why:"קו אופקי וקו אנכי נפגשים בזווית ישרה, כמו הצירים. לכן הקטע בין הנקודות הוא יתר, ומשפט פיתגורס נותן את אורכו."},{kind:"predict",fig:{type:"coord",range:6,segments:[[[-3,2],[3,2]]]},text:"האם משנה אם מחשבים $3 - (-3)$ או $-3 - 3$?",choices:["כן, יוצאות תשובות שונות","לא, אחרי שמרבעים זה אותו דבר"],answer:1,why:"$6^2 = 36$ וגם $(-6)^2 = 36$. הריבוע מוחק את הסימן, ולכן לא משנה מאיזו נקודה מתחילים.",wrongWhy:{0:"לפני הריבוע יוצא $6$ או $-6$. אבל $6^2$ ו־$(-6)^2$ שניהם $36$."}},{kind:"say",fig:{type:"coord",range:6,polygon:[[-3,2],[3,2],[3,-6]],segments:[[[-3,2],[3,-6]]]},text:"בדיקת שכל: המרחק בקו ישר ארוך מכל אחד מההפרשים, וקצר מהסכום שלהם."}],examples:[{problem:"מה המרחק בין $A(-1, 2)$ ל־$B(11, 7)$?",display:"A(-1, 2) \\qquad B(11, 7)",answer:13,check:"sqrt((11 - (-1))^2 + (7 - 2)^2)",fig:{type:"coord",range:12,points:[{x:-1,y:2,label:"A"},{x:11,y:7,label:"B"}],segments:[[[-1,2],[11,7]]],helper:[[-1,2],[11,2],[11,7]]},steps:[{action:"מחשבים את ההפרש ב־$x$: הניצב האופקי.",why:"מ־$-1$ עד $11$: צעד אחד עד האפס ועוד $11$.",result:"11 - (-1) = 12",calc:{expr:"11 - (-1)",value:12}},{action:"מחשבים את ההפרש ב־$y$: הניצב האנכי.",why:"מ־$2$ עד $7$.",result:"7 - 2 = 5",calc:{expr:"7 - 2",value:5}},{action:"פיתגורס: מרבעים ומחברים.",why:"הקטע $AB$ הוא היתר של המשולש.",result:"d^2 = 12^2 + 5^2 = 144 + 25 = 169",calc:{expr:"12^2 + 5^2",value:169}},{action:"מוציאים שורש.",why:"מהשטח לאורך.",result:"d = \\sqrt{169} = 13",value:"sqrt(169)"}]},{problem:"במפה של שכונה כל משבצת היא $100$ מטר. הבית של דנה ב־$(-2, -1)$, ובית הספר ב־$(4, 7)$. מה המרחק ביניהם בקו אווירי, במטרים?",answer:1e3,check:"sqrt((4 - (-2))^2 + (7 - (-1))^2) * 100",fig:{type:"coord",range:8,points:[{x:-2,y:-1,label:""},{x:4,y:7,label:""}],segments:[[[-2,-1],[4,7]]],helper:[[-2,-1],[4,-1],[4,7]],words:[{at:[-2,-2.2],text:"בית"},{at:[2,7],text:"בית ספר"}]},steps:[{action:"ההפרש ב־$x$.",why:"מ־$-2$ עד $4$ עוברים את האפס: $2 + 4$ צעדים.",result:"4 - (-2) = 6",calc:{expr:"4 - (-2)",value:6}},{action:"ההפרש ב־$y$.",why:"מ־$-1$ עד $7$: $1 + 7$ צעדים.",result:"7 - (-1) = 8",calc:{expr:"7 - (-1)",value:8}},{action:"המרחק במשבצות.",why:"הקו האווירי הוא היתר של משולש עם ניצבים $6$ ו־$8$.",result:"d = \\sqrt{6^2 + 8^2} = \\sqrt{100} = 10",calc:{expr:"sqrt(6^2 + 8^2)",value:10}},{action:"ממירים למטרים.",why:"כל משבצת היא $100$ מטר.",result:"10 \\cdot 100 = 1000",value:"10 * 100"},{action:"משווים להליכה ברחובות.",why:"ברחובות, ימינה ואז למעלה, הולכים $6 + 8 = 14$ משבצות. בקו אווירי חוסכים $400$ מטר.",result:"(6 + 8) \\cdot 100 = 1400",calc:{expr:"(6 + 8) * 100",value:1400}}]}],together:[{problem:"נמצא יחד את המרחק בין $P$ ל־$Q$.",display:"P(-5, 4) \\qquad Q(4, -8)",fig:{type:"coord",range:9,points:[{x:-5,y:4,label:"P"},{x:4,y:-8,label:"Q"}],segments:[[[-5,4],[4,-8]]],helper:[[-5,4],[-5,-8],[4,-8]]},steps:[{prompt:"מה אורך הניצב האופקי?",choices:[{text:"$4 - (-5) = 9$",ok:!0,feedback:"נכון: מ־$-5$ עד $4$ עוברים את האפס, $5 + 4 = 9$ צעדים."},{text:"$5 - 4 = 1$",ok:!1,misc:"coord-diff",feedback:"ה־$x$ של $P$ הוא $-5$, לא $5$. מ־$-5$ עד $4$ עוברים את האפס: $5 + 4 = 9$ צעדים."},{text:"$4 - (-8) = 12$",ok:!1,feedback:"זה הפרש בין $y$ ל־$y$. הניצב האופקי משווה רק את שיעורי ה־$x$: $-5$ ו־$4$."}],hints:["השיעורים: ה־$x$ של $P$ הוא $-5$, ושל $Q$ הוא $4$.","$4 - (-5) = 4 + 5 = 9$."],done:"הניצב האופקי $9$."},{prompt:"מה אורך הניצב האנכי?",choices:[{text:"$4 - (-8) = 12$",ok:!0,feedback:"נכון: מ־$4$ יורדים עד $-8$, ארבעה צעדים עד האפס ועוד שמונה."},{text:"$8 - 4 = 4$",ok:!1,misc:"coord-diff",feedback:"ה־$y$ של $Q$ הוא $-8$. כשהקטע חוצה את ציר $x$, הצעדים משני הצדדים מצטרפים: $4 + 8 = 12$."},{text:"$4 - (-5) = 9$",ok:!1,feedback:"זה הניצב האופקי, שכבר מצאנו. עכשיו משווים את שיעורי ה־$y$: $4$ ו־$-8$."}],hints:["השיעורים: ה־$y$ של $P$ הוא $4$, ושל $Q$ הוא $-8$.","$4 - (-8) = 4 + 8 = 12$."],done:"הניצב האנכי $12$."},{prompt:"מה עושים עם $9$ ו־$12$?",choices:[{text:"$\\sqrt{9^2 + 12^2}$",ok:!0,feedback:"נכון: הקטע $PQ$ הוא היתר."},{text:"$9 + 12 = 21$",ok:!1,misc:"add-legs",feedback:"זו הדרך במדרגות, לאורך קווי הרשת. הקו הישר קצר יותר."},{text:"$9^2 + 12^2 = 225$",ok:!1,misc:"no-root",feedback:"זה השטח של הריבוע על $PQ$. חסר עוד צעד אחד."}],hints:["$PQ$ הוא יתר. איך מוצאים יתר?","מרבעים, מחברים ומוציאים שורש: $\\sqrt{81 + 144}$."],done:"$PQ = \\sqrt{81 + 144} = \\sqrt{225}$"}],final:{prompt:"מה המרחק $PQ$?",answer:15,check:"sqrt((4 - (-5))^2 + (-8 - 4)^2)",hints:["איזה מספר כפול עצמו נותן $225$?","$15 \\cdot 15 = 225$."]}}],diag:O$,transfer:H$,misconceptions:[{id:"add-legs",title:"חיברו את ההפרש ב־$x$ ואת ההפרש ב־$y$, בלי לרבע",cause:"זו הדרך לאורך קווי הרשת, ימינה ואז למעלה. המרחק הוא הקו הישר, היתר, והוא קצר יותר.",explain:["נראה שחיברתם את שני ההפרשים. כך הולכים במדרגות, לאורך המשבצות.","המרחק בין נקודות הוא קו ישר: היתר של המשולש. מ־$(0, 0)$ ל־$(3, 4)$ במדרגות $7$, ובקו ישר $5$.","מרבעים את ההפרשים, מחברים, ומוציאים שורש."],remedy:[{kind:"predict",text:"מ־$(0, 0)$ ל־$(3, 4)$ ההליכה במשבצות היא $3 + 4 = 7$. והקו הישר?",choices:["גם $7$","קצר יותר: $5$"],answer:1,why:"הקו הישר הוא היתר: $\\sqrt{9 + 16} = 5$. קו ישר הוא הדרך הקצרה."},{kind:"explore",text:"ההפרש ב־$x$ הוא $6$, וב־$y$ הוא $8$. בנו את המשולש וראו מה יוצא על היתר.",manip:i(2,2),answer:{c:10,a:6,b:8},hint:"קבעו ניצבים $6$ ו־$8$.",success:"על היתר $100$, ולכן המרחק $10$, ולא $6 + 8 = 14$."}],prereq:"pyth:1"},{id:"no-root",title:"עצרו בסכום הריבועים ושכחו להוציא שורש",cause:"סכום ריבועי ההפרשים הוא השטח של הריבוע על הקטע, לא אורך הקטע.",explain:["החישוב היה נכון עד הצעד האחרון. $(\\Delta x)^2 + (\\Delta y)^2$ הוא שטח.","בדיקת שכל: המרחק צריך להיות קצר מסכום ההפרשים. אם יצא מספר גדול בהרבה, חסר שורש."],remedy:[{kind:"predict",text:"ההפרשים $5$ ו־$12$, ויצא $d^2 = 169$. מה המרחק?",choices:["$169$","$13$"],answer:1,why:"$169$ הוא השטח של הריבוע על הקטע. המרחק הוא $\\sqrt{169} = 13$, קצר מ־$5 + 12 = 17$ כמו שצריך."},{kind:"explore",text:"בנו משולש עם ניצבים $5$ ו־$12$. השטח על היתר $169$. כמה ארוך היתר?",manip:i(5,2),answer:{c:13,a:5,b:12},hint:"השאירו ניצב $5$, וקבעו את השני על $12$.",success:"השטח $169$, והאורך $13$, כי $13 \\cdot 13 = 169$."}],prereq:"pyth:1"},{id:"coord-diff",title:"חיסרו שיעורים בלי הסימנים, כשהקטע חוצה ציר",cause:"כשנקודה אחת בצד השלילי והשנייה בצד החיובי, הקטע עובר דרך האפס. הצעדים משני צדי האפס מצטרפים, ולכן ההפרש הוא סכום המרחקים מהאפס.",explain:["נראה שאחד הניצבים יצא קצר מדי, כי השיעורים חוסרו בלי הסימנים שלהם.","מ־$-2$ עד $4$: שני צעדים עד האפס, ועוד ארבעה אחריו. ביחד $6$. בחשבון $4 - (-2) = 6$, ולא $4 - 2$.","חיסור של מספר שלילי הוא חיבור של הנגדי שלו."],remedy:[{kind:"explore",text:"כמה צעדים מ־$-2$ עד $4$? הזיזו את הסמן מ־$-2$ אל $4$ וספרו.",display:"-2 + 6",manip:{kind:"numberline",min:-10,max:10,from:-2,start:-2},answer:4,hint:"עד האפס $2$ צעדים, ומשם עוד $4$.",success:"מ־$-2$ עד $4$ יש $6$ צעדים: $4 - (-2) = 6$."},{kind:"predict",text:"מה אורך הניצב האנכי בין $(1, -5)$ ל־$(1, 3)$?",choices:["$2$","$8$"],answer:1,why:"מ־$-5$ עד $3$: חמישה צעדים עד האפס ועוד שלושה. $3 - (-5) = 8$."}],prereq:"coord:3"}]},Y$=[p$,v$,P$,Q$,T$],N$={"wrong-hyp":"זיהו לא נכון מי היתר","assume-right":"הניחו שהמשולש ישר־זווית בלי לבדוק","coord-diff":"חיסרו שיעורים בלי הסימנים כשהקטע חוצה ציר"};export{N$ as CATS_PYTH,Y$ as PYTH,O$ as distModel,f$ as hypModel,R$ as ladderModel,m$ as legModel,C$ as testModel};
